___CSS_LOADER_EXPORT___.push([module.id, `/* Icon面板样式 */
.svg-pannel-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  border-radius: 8px;
  overflow: hidden;
  max-width: 100%;
  width: 252px;
  height: 100%;
  background: #ffffff;
  display: flex;
  flex-direction: column;
}
/* 控制区域样式 */
.icon-control-area {
  background: #ffffff;
  padding: 8px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-shrink: 0;
}
/* 搜索框样式 */
.icon-search-container {
  position: relative;
  flex: 1;
}
.icon-search-input {
  width: 100%;
  height: 26px;
  padding: 0 32px 0 32px;
  border: 1px solid #e9edf2;
  border-radius: 4px;
  font-size: 12px;
  color: #212930;
  outline: none;
  box-sizing: border-box;
}
.icon-search-input:focus {
  border-color: #067bef;
}
.icon-search-input::placeholder {
  color: #c0c4cc;
}
.icon-search-icon {
  position: absolute;
  left: 8px;
  width: 20px;
  height: 20px;
  line-height: 20px;
  text-align: center;
  top: 50%;
  transform: translateY(-50%);
  font-size: 16px;
  color: #9aa5b8;
  pointer-events: none;
}
.icon-search-clear {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  line-height: 20px;
  text-align: center;
  font-size: 16px;
  color: #a6b9cd;
  cursor: pointer;
  border-radius: 50%;
  display: none;
  transition: all 0.3s;
}
/* 分类选择器样式 */
.icon-control-area .category-select {
  width: 100%;
}
/* 内容区域样式 */
.content-area {
  padding: 0 16px;
  background: #ffffff;
  overflow-y: auto;
  overflow-x: hidden;
  flex: 1;
  min-height: 0;
}
/* 分类标题样式 */
.category-title {
  font-size: 11px;
  font-weight: 400;
  color: #6c7d8f;
  line-height: 20px;
}
/* 图标网格样式 */
.svg-items-grid {
  padding: 8px 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, 32px);
  gap: 12px 11px;
}
/* SVG项目样式 */
.svg-item {
  border: 1px solid rgba(33, 41, 48, 0.12);
  border-radius: 4px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: white;
  position: relative;
  overflow: hidden;
}
.svg-item:hover {
  background-color: rgba(33, 41, 48, 0.06);
}
.svg-item.selected {
  border-color: #067bef;
}
/* 图标容器样式 */
.svg-icon-container {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.svg-icon {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #606266;
  transition: color 0.3s ease;
}
.svg-item:hover .svg-icon {
  color: #409eff;
}
.svg-item.selected .svg-icon {
  color: #409eff;
}
/* 图标信息样式（如果需要显示图标名称可以启用） */
.svg-info {
  width: 100%;
  text-align: center;
  overflow: hidden;
}
.svg-name {
  font-size: 12px;
  color: #606266;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 500;
}
.svg-desc {
  font-size: 11px;
  color: #909399;
  line-height: 1.4;
  margin-top: 2px;
}
/* 无数据状态 */
.no-data {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  text-align: center;
  padding: 80px 20px;
  color: #909399;
  font-size: 12px;
}
.no-data .no-data-icon {
  font-size: 48px;
  color: #dcdfe6;
  margin-bottom: 16px;
}
.no-data .no-data-text {
  font-size: 14px;
  color: #909399;
  line-height: 1.5;
}
/* 主题样式适配 */
.svg-pannel-wrapper.theme-outline {
  background: #ffffff;
}
.svg-pannel-wrapper.theme-filled {
  background: #f8f9fa;
}
.svg-pannel-wrapper.theme-two-tone {
  background: linear-gradient(135deg, #f8f9fa 0%, #ffffff 100%);
}
/* 头部标题样式 */
.icon-panel-header {
  height: 40px;
  line-height: 40px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 700;
  color: #212930;
  background: #ffffff;
  border-bottom: 1px solid #e5e5e5;
  flex-shrink: 0;
}
/* 底部来源信息样式 */
.icon-panel-footer {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 16px;
  font-size: 12px;
  color: #6c7d8f;
  background: #fff;
  border-top: 1px solid #2129301f;
  text-align: center;
}
.icon-panel-footer .img {
  margin-left: 8px;
  display: inline-block;
  width: 73px;
  height: 25px;
}
/* 占位符样式 */
.svg-item-placeholder {
  width: 32px;
  height: 32px;
  background: #f5f7fa;
  border: 1px solid rgba(33, 41, 48, 0.12);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
  cursor: default;
}
.svg-item-placeholder::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
  animation: shimmer 1.5s infinite;
}
@keyframes shimmer {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}
`, ""]);
