class HistoryManager {
  constructor(editor, options = {}) {
    this.editor = editor;
    this.undoStack = [];
    this.redoStack = [];
    this.limit = options.limit || 50;
    this.enableStack = options.enableStack !== false; // Default true
    this.isExecuting = false; // To prevent recording history during undo/redo
    this.commandMap = {
      [COMMAND_TYPE.ADD_SHAPE]: AddShapeCommand,
      [COMMAND_TYPE.REMOVE_SHAPE]: RemoveShapeCommand,
      [COMMAND_TYPE.UPDATE_SHAPE]: UpdateShapeCommand,
      [COMMAND_TYPE.REPLACE_DATA]: ReplaceDataCommand,
      [COMMAND_TYPE.DELEGATED]: DelegatedCommand,
      [COMMAND_TYPE.UPDATE_SMART_GRAPHIC_TYPE]: UpdateSmartGraphicTypeCommand,
      // Mapping class names for backward compatibility or direct instantiation
      AddShapeCommand: AddShapeCommand,
      RemoveShapeCommand: RemoveShapeCommand,
      UpdateShapeCommand: UpdateShapeCommand,
      ReplaceDataCommand: ReplaceDataCommand,
      DelegatedCommand: DelegatedCommand,
      UpdateSmartGraphicTypeCommand: UpdateSmartGraphicTypeCommand
    };
  }
  canUndo() {
    return this.undoStack.length > 0;
  }
  canRedo() {
    return this.redoStack.length > 0;
  }
  push(command) {
    if (this.isExecuting) return;

    // Capture the selection state after the command execution
    // if (!command.data.selectedIdsAfter) {
    //   command.data.selectedIdsAfter = this.editor.getSelectedIds();
    // }

    if (!command.data.selectedIdsBefore) {
      command.data.selectedIdsBefore = this.editor.getSelectedIds();
    }

    // Always emit the PUSH_HISTORY event with serialized command
    if (this.editor.emit) {
      this.editor.emit(EDITOR_EVENT_TYPES.PUSH_HISTORY, command.toJSON());
    }

    // Only modify internal stack if enabled
    if (this.enableStack) {
      this.undoStack.push(command);
      if (this.undoStack.length > this.limit) {
        this.undoStack.shift();
      }
      this.redoStack = []; // Clear redo stack on new action
      this.emitChange('push');
    }
  }

  /**
   * Execute a command from external JSON data
   * @param {Object} jsonCommand - Serialized command data
   * @param {string} actionType - 'undo' | 'redo' | 'execute'
   */
  execute(jsonCommand, actionType = 'execute') {
    const CommandClass = this.commandMap[jsonCommand.type];
    if (!CommandClass) {
      console.warn(`Unknown command type: ${jsonCommand.type}`);
      return;
    }
    const command = new CommandClass(this.editor, jsonCommand.data);
    this.isExecuting = true;
    try {
      if (actionType === 'undo') {
        if (!command.data) command.data = {};
        command.undo();
      } else if (actionType === 'redo') {
        if (!command.data) command.data = {};
        command.redo();
      } else {
        command.execute();
      }
    } finally {
      this.isExecuting = false;
    }
  }
  undo() {
    if (!this.enableStack) return; // Disable internal undo if stack is disabled
    if (this.undoStack.length === 0) return;
    const command = this.undoStack.pop();
    if (!command.data) command.data = {};
    if (!command.data.selectedIdsAfter) {
      command.data.selectedIdsAfter = this.editor.getSelectedIds();
    }
    this.redoStack.push(command);
    this.isExecuting = true;
    command.undo();
    this.isExecuting = false;
    this.emitChange('undo');
  }
  redo() {
    if (!this.enableStack) return; // Disable internal redo if stack is disabled
    if (this.redoStack.length === 0) return;
    const command = this.redoStack.pop();
    this.undoStack.push(command);
    const selectedIdsBefore = this.editor?.getSelectedIds?.() || [];
    if (!command.data) command.data = {};
    command.data.selectedIdsBefore = selectedIdsBefore;
    this.isExecuting = true;
    command.redo();
    this.isExecuting = false;
    this.emitChange('redo');
  }
  clear() {
    this.undoStack = [];
    this.redoStack = [];
    this.emitChange('clear');
  }
  emitChange(source) {
    this.editor.emit(EDITOR_EVENT_TYPES.HISTORY_CHANGE, {
      canUndo: this.undoStack.length > 0,
      canRedo: this.redoStack.length > 0,
      undoLength: this.undoStack.length,
      redoLength: this.redoStack.length,
      source
    });
  }
}
