class Section extends events.EventEmitter {
  constructor(options) {
    super();
    this._locale = options.locale;
    return this.render(...arguments);
  }
  render(options) {
    const {
      content,
      contentX,
      contentY,
      contentW,
      contentH,
      bgFill,
      sectionTextStyle,
      sectionBgStyle: {
        fill
      },
      adaptiveBgColor,
      onChange = () => {}
    } = options;
    const text = content?.text;
    const classNames = [CLASS_LAYER_SECTION_TITLE];
    if (!text) {
      classNames.unshift(CLASS_LAYER_SECTION_TITLE_PLACEHOLDER);
    }
    const _fill = fill || bgFill;
    let color = sectionTextStyle.color;
    let placeholderColor = sectionTextStyle.placeholderColor || sectionTextStyle.color;
    if (adaptiveBgColor) {
      const isLight = (0,tools/* isLightColor */.eX)(_fill === 'transparent' ? '#FFF' : _fill || '#FFF');
      color = isLight ? sectionTextStyle.colorDark : sectionTextStyle.color;
      placeholderColor = (isLight ? sectionTextStyle.placeholderColorDark : sectionTextStyle.placeholderColor) || color;
    }
    const _selfStyle = content?.style || {};
    const _content = new RichText({
      className: classNames.join(' '),
      x: contentX,
      y: contentY,
      text,
      style: {
        ...sectionTextStyle,
        ..._selfStyle,
        width: contentW,
        height: contentH,
        color,
        placeholderColor,
        placeholder: this._locale.get('section.placeholder'),
        cursor: 'text'
      },
      onChange
    });
    return _content.getElement();
  }
}
