/**
 * ProxyBase
 * 基类：提供事件系统 + 子实例方法透传 + 子事件代理
 *
 * 子类只需设置 this.currentChild = new XXX()，就自动拥有：
 * - this.on / this.emit 事件机制
 * - 子实例的 emit 会冒泡到父级
 * - Proxy 自动透传子实例方法
 */
class ProxyBase {
  constructor() {
    this._listeners = {};
    this.currentChild = null;

    // 使用 Proxy 自动透传方法
    return new Proxy(this, {
      get: (target, prop, receiver) => {
        // 优先返回父类自身属性
        if (prop in target) return Reflect.get(target, prop, receiver);

        // 如果 currentChild 存在同名属性/方法，则透传
        const child = target.currentChild;
        if (child && prop in child) {
          const value = child[prop];
          return typeof value === 'function' ? value.bind(child) : value;
        }
      }
    });
  }

  /** 注册事件 */
  on(event, handler) {
    (this._listeners[event] || (this._listeners[event] = [])).push(handler);
  }

  /** 触发事件 */
  emit(event, ...args) {
    (this._listeners[event] || []).forEach(fn => fn(...args));
  }

  /**
   * 绑定事件桥接：让子实例 emit 自动冒泡到父级
   * @param {Object} child 子实例
   */
  bindChildEvents(child) {
    if (!child || typeof child.emit !== 'function') return;
    if (!child._emitDelegated) {
      const originalEmit = child.emit.bind(child);
      child.emit = (event, ...args) => {
        // 子 emit 自身逻辑
        originalEmit(event, ...args);
        // 同步冒泡到父级
        this.emit(event, ...args);
      };
      child._emitDelegated = true;
    }
  }

  /** 移除当前子实例 */
  destroyChild() {
    if (this.currentChild?.destroy) {
      this.currentChild.destroy();
    }
    this.currentChild = null;
  }

  /** 销毁当前实例 */
  destroy() {
    this.destroyChild();
    this._listeners = {};
  }
}
