/**
 * BasePanel
 * 面板基类，集成 EventEmitter + 事件冒泡机制
 *
 * 所有继承的子类自动获得：
 * - this.on(event, handler)
 * - this.emit(event, ...args)  // 支持向父面板冒泡
 * - this.setParent(parent)
 */
class BasePanel extends events.EventEmitter {
  editor;
  container;
  rootNode;
  constructor(options = {}) {
    super();
    const {
      editor,
      container,
      ...restOptions
    } = options;
    // 必选参数校验
    if (!options.editor || !options.container) {
      throw new Error('必须提供 editor 和 container 参数');
    }
    this.editor = editor;
    this.container = container;
    this.options = Object.assign({}, restOptions);
    /** @type {BasePanel|null} 父面板引用，用于事件冒泡 */
    this.parent = null;
  }
  /**
   * 设置父面板（用于事件冒泡链）
   * @param {BasePanel} parent
   */
  setParent(parent) {
    this.parent = parent;
  }

  /**
   * emit 增强版
   * - 触发当前面板的监听器
   * - 自动向上冒泡（父面板 emit）
   * @param {string} event
   * @param  {...any} args
   */
  emit(event, ...args) {
    // ✅ 触发自身监听器
    super.emit(event, ...args);

    // 🚀 向上冒泡
    if (this.parent && typeof this.parent.emit === 'function') {
      this.parent.emit(event, ...args);
    }
  }
  render() {}
  destroy() {
    this.removeAllListeners();
    if (this.rootNode?.parentNode) {
      this.rootNode.parentNode?.removeChild(this.rootNode);
    }
    this.parent = null;
    this.editor = null;
    this.rootNode = null;
    this.container = null;
  }
}
