/**
 * SelectionHelper
 * 用于分析 editor.getSelected() 的结果
 * - 带缓存机制（避免重复计算）
 * - 自动清理缓存（事件驱动）
 */
class SelectionHelper {
  static _cache = {
    lastSelectedIds: null,
    lastState: null,
    _watcherBound: false
  };

  /**
   * 获取当前选中状态（带缓存 + 自动事件清理）
   * @param {Object} editor - 编辑器实例，必须包含 getSelected()
   * @returns {Object} selectionState
   */
  static getSelectionState(editor) {
    if (!editor || typeof editor.getSelected !== 'function') {
      console.warn('[SelectionHelper] editor 无效或未实现 getSelected');
      return {};
    }
    const selected = editor.getSelected();
    const selectedIds = SelectionHelper._buildSignature(selected);

    // 如果签名没变，直接用缓存
    if (SelectionHelper._cache.lastSelectedIds === selectedIds) {
      return SelectionHelper._cache.lastState;
    }
    const state = {
      isShapeSelected: !!selected
    };

    // 写入缓存
    SelectionHelper._cache.lastSelectedIds = selectedIds;
    SelectionHelper._cache.lastState = state;

    // 注册监听，仅绑定一次
    SelectionHelper._bindEditorWatcher(editor);
    return state;
  }

  /**
   * 判断是否为助手节点
   */
  static isAssistantNode(shape) {
    if (!shape) return false;
    return !!shape.isAssist;
  }

  /**
   * 清空缓存
   */
  static clearCache() {
    SelectionHelper._cache.lastSelectedIds = null;
    SelectionHelper._cache.lastState = null;
  }

  /**
   * 绑定编辑器事件，自动清理缓存
   * @private
   */
  static _bindEditorWatcher(editor) {
    if (SelectionHelper._cache._watcherBound) return;
    if (!editor || typeof editor.on !== 'function') return;
    // 监听选中变化 / 节点变化 / 文档重置 等事件自动清理缓存
    const events = ['layer-unselected'];
    events.forEach(event => {
      editor.on(event, () => {
        SelectionHelper.clearCache();
      });
    });
    SelectionHelper._cache._watcherBound = true;
  }

  /**
   * 根据 selected 生成签名字符串
   * @private
   */
  static _buildSignature(selected = {}) {
    return selected ? `${selected.id || ''}` : '';
  }
}
;// ./src/packages-ui/pyramid/panel/index.js





/**
 * SettingPanel 主控制类（最终优化版）
 * - 动态切换 Shape / Linker 面板
 * - 同时确保 container 中只存在一个面板 DOM
 * - 保留缓存机制，面板切换时仅挂载/卸载
 * - 继承 ProxyBase：事件透传 + 方法代理 + 事件冒泡
 */
class SettingPanel extends ProxyBase {
  constructor(options = {}) {
    super();
    if (!options.editor || !options.container) {
      throw new Error('必须提供 editor 和 container 参数');
    }
    this.setEditor(options.editor);
    this.container = options.container;
    this.options = options;
    this.currentChild = null;
    this.panelCache = new Map();
  }
  setEditor(editor) {
    this.editor = editor;
  }
  /** 渲染当前应显示的面板 */
  render(editor) {
    if (editor) {
      this.setEditor(editor);
    }
    const selectionState = SelectionHelper.getSelectionState(this.editor);
    const panelType = !('isShapeSelected' in selectionState) || selectionState.isShapeSelected ? 'shape' : 'global';
    // 如果当前面板类型一致，则直接刷新
    if (this.currentChild && this.currentChild.type === panelType) {
      this.currentChild.refresh?.(this.editor);
      return;
    }

    // 否则切换面板
    this.switchPanel(panelType);
  }

  /**
   * 切换面板（带缓存复用）
   * @param {'global'} panelType
   */
  switchPanel(panelType) {
    // 1️⃣ 移除当前面板（确保只有一个 panel）
    if (this.currentChild?.rootNode) {
      this.container.removeChild(this.currentChild.rootNode);
    }

    // 2️⃣ 卸载当前面板（但保留实例）
    if (this.currentChild) {
      this.currentChild.onHide?.(); // 可选：触发隐藏钩子
    }

    // 3️⃣ 复用或创建新的面板实例
    let panel = this.panelCache.get(panelType);
    if (!panel) {
      panel = panelType === 'shape' ? new BasePanel(this.options) : new ShapeSettingPanel(this.options);
      panel.type = panelType;
      this.bindChildEvents(panel);
      this.panelCache.set(panelType, panel);
    }
    // 4️⃣ 重新挂载 DOM
    panel.container = this.container;
    panel.render();
    panel.onShow?.();
    this.currentChild = panel;
  }

  /** 获取当前面板实例 */
  getCurrentPanel() {
    return this.currentChild;
  }

  /**
   * 清空缓存（彻底销毁所有面板）
   */
  clearCache() {
    for (const panel of this.panelCache.values()) {
      panel.destroy?.();
    }
    this.panelCache.clear();
    this.currentChild = null;
    if (this.container) {
      this.container.innerHTML = '';
    }
  }

  /** 销毁整个 SettingPanel 实例 */
  destroy() {
    this.clearCache();
    this.editor = null;
    this.container = null;
    super.destroy();
  }
}
