class JSONPayloadSanitizer {
  static sanitize(raw) {
    if (!raw || typeof raw !== 'string') return '';
    let text = raw;

    // 1. 移除 BOM / 空字符
    // eslint-disable-next-line no-control-regex
    text = text.replace(/^\uFEFF/, '').replace(/\u0000/g, '');

    // 2. 移除 Markdown fence（所有变体）
    text = text.replace(/```json\s*/gi, '').replace(/```js\s*/gi, '').replace(/```\s*/g, '');

    // 3. 移除 SSE 行前缀
    text = text.replace(/^data:\s*/gm, '');

    // 4. 去掉明显的引导性文本（仅在 JSON 之前）
    const firstBrace = text.search(/[{[]/);
    if (firstBrace === -1) return '';
    text = text.slice(firstBrace);

    // 5. 截取完整 JSON（支持 {} 和 []）
    return JSONPayloadSanitizer._extractCompleteJSON(text);
  }
  static _extractCompleteJSON(text) {
    const startChar = text[0];
    const endChar = startChar === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = 0; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
        continue;
      }
      if (ch === startChar) depth++;
      if (ch === endChar) depth--;
      if (depth === 0) {
        return text.slice(0, i + 1);
      }
    }

    // 不完整 JSON，直接返回原始截断结果
    return text;
  }
}
