// upstreamdeep: 获取所有上游节点
function upstreamdeep(node, items) {
  const res = [];
  let current = node;
  const visited = new Set();
  while (current.parent) {
    const parentNode = items[current.parent];
    if (!parentNode || visited.has(parentNode.id)) break;
    visited.add(parentNode.id);
    res.push(parentNode);
    current = parentNode;
  }
  return res;
}

// downstream: 获取直接下游节点
