/**
 * 插件管理器
 * 负责管理 OrgChart 的所有插件
 */
class PluginManager {
  constructor(orgChart) {
    this.orgChart = orgChart;
    this.plugins = new Map();
    this.pluginOrder = [];
  }

  /**
   * 注册插件
   * @param {BasePlugin} plugin - 插件实例
   * @param {number} priority - 插件优先级，数字越小优先级越高
   */
  async register(plugin, priority = 100) {
    if (!plugin || !plugin.name) {
      throw new Error('Plugin must have a name');
    }
    if (this.plugins.has(plugin.name)) {
      console.warn(`Plugin "${plugin.name}" is already registered`);
      return;
    }
    try {
      // 异步初始化插件
      await plugin.init(this.orgChart);

      // 注册插件
      this.plugins.set(plugin.name, {
        plugin,
        priority
      });

      // 更新插件顺序
      this.updatePluginOrder();
      console.log(`Plugin "${plugin.name}" registered successfully`);
    } catch (error) {
      console.error(`Failed to register plugin "${plugin.name}":`, error);
      throw error;
    }
  }

  /**
   * 注销插件
   * @param {string} name - 插件名称
   */
  unregister(name) {
    const pluginInfo = this.plugins.get(name);
    if (pluginInfo) {
      pluginInfo.plugin.destroy();
      this.plugins.delete(name);
      this.updatePluginOrder();
      console.log(`Plugin "${name}" unregistered successfully`);
    }
  }

  /**
   * 获取插件
   * @param {string} name - 插件名称
   * @returns {BasePlugin|null}
   */
  get(name) {
    const pluginInfo = this.plugins.get(name);
    return pluginInfo ? pluginInfo.plugin : null;
  }

  /**
   * 检查插件是否存在
   * @param {string} name - 插件名称
   * @returns {boolean}
   */
  has(name) {
    return this.plugins.has(name);
  }

  /**
   * 启用插件
   * @param {string} name - 插件名称
   */
  enable(name) {
    const plugin = this.get(name);
    if (plugin) {
      plugin.enable();
    }
  }

  /**
   * 禁用插件
   * @param {string} name - 插件名称
   */
  disable(name) {
    const plugin = this.get(name);
    if (plugin) {
      plugin.disable();
    }
  }

  /**
   * 获取所有插件名称
   * @returns {string[]}
   */
  getPluginNames() {
    return Array.from(this.plugins.keys());
  }

  /**
   * 获取所有启用的插件
   * @returns {BasePlugin[]}
   */
  getEnabledPlugins() {
    return this.pluginOrder.map(name => this.get(name)).filter(plugin => plugin && plugin.enabled);
  }

  /**
   * 更新插件顺序
   */
  updatePluginOrder() {
    this.pluginOrder = Array.from(this.plugins.entries()).sort(([, a], [, b]) => a.priority - b.priority).map(([name]) => name);
  }

  /**
   * 渲染所有插件
   */
  render() {
    this.getEnabledPlugins().forEach(plugin => {
      try {
        plugin.render();
      } catch (error) {
        console.error(`Error rendering plugin "${plugin.name}":`, error);
      }
    });
  }

  /**
   * 更新所有插件
   */
  update() {
    this.getEnabledPlugins().forEach(plugin => {
      try {
        plugin.update();
      } catch (error) {
        console.error(`Error updating plugin "${plugin.name}":`, error);
      }
    });
  }

  /**
   * 销毁所有插件
   */
  destroy() {
    this.plugins.forEach(({
      plugin
    }) => {
      try {
        plugin.destroy();
      } catch (error) {
        console.error(`Error destroying plugin "${plugin.name}":`, error);
      }
    });
    this.plugins.clear();
    this.pluginOrder = [];
    this.orgChart = null;
  }
}
