/**
 * 分层主题管理器
 */
class LevelThemeManager {
  constructor() {
    this.currentTheme = LEVEL_THEMES[0];
  }

  /**
   * 获取所有主题
   * @returns {Array} 主题列表
   */
  getAllThemes() {
    return LEVEL_THEMES;
  }

  /**
   * 根据ID获取主题
   * @param {string} themeId 主题ID
   * @returns {Object|null} 主题配置
   */
  getThemeById(themeId) {
    return LEVEL_THEMES.find(theme => theme.id === themeId) || null;
  }

  /**
   * 计算节点层级
   * @param {Object} nodeData 节点数据
   * @param {Object} allNodes 所有节点数据 { [id]: nodeData }
   * @returns {number} 层级数（0为根节点）
   */
  calculateNodeLevel(nodeData, allNodes) {
    let level = 0;
    let currentNode = nodeData;

    // 向上遍历到根节点
    while (currentNode && currentNode.parent) {
      level++;
      currentNode = allNodes[currentNode.parent];

      // 防止无限循环
      if (level > 10) break;
    }
    return level;
  }

  /**
   * 根据层级获取颜色
   * @param {string} themeId 主题ID
   * @param {number} level 节点层级
   * @returns {Object|null} 颜色配置 { fill, stroke, text }
   */
  getColorsForLevel(themeId, level) {
    const theme = this.getThemeById(themeId);
    if (!theme) return null;

    // 如果层级超过定义范围，使用最后一个层级的颜色
    const maxLevel = Math.max(...Object.keys(theme.levels).map(Number));
    const effectiveLevel = Math.min(level, maxLevel);
    return theme.levels[effectiveLevel] || theme.levels[maxLevel];
  }

  /**
   * 设置主题中某个层级的颜色
   * @param {string} themeId 主题ID
   * @param {number} level 层级
   * @param {Object} colors 颜色配置 { fill, stroke, text }
   */
  setLevelColors(themeId, level, colors) {
    const theme = this.getThemeById(themeId);
    if (!theme) return false;
    theme.levels[level] = {
      ...colors
    };
    return true;
  }

  /**
   * 创建自定义主题
   * @param {string} id 主题ID
   * @param {string} name 主题名称
   * @param {Object} levels 层级颜色配置
   * @returns {Object} 新创建的主题
   */
  createCustomTheme(id, name, levels) {
    const customTheme = {
      id,
      name,
      description: '自定义主题',
      levels: {
        ...levels
      }
    };

    // 添加到主题列表
    LEVEL_THEMES.push(customTheme);
    return customTheme;
  }

  /**
   * 为整个组织架构应用分层主题
   * @param {string} themeId 主题ID
   * @param {Object} orgData 组织架构数据 { items: {...}, itemOrder: {...} }
   * @returns {Object} 应用主题后的配置
   */
  applyLevelTheme(themeId, orgData) {
    const theme = this.getThemeById(themeId);
    if (!theme || !orgData.items) return {};
    const result = {
      items: {}
    };

    // 为每个节点计算层级并应用对应颜色
    Object.keys(orgData.items).forEach(nodeId => {
      const nodeData = orgData.items[nodeId];
      const level = this.calculateNodeLevel(nodeData, orgData.items);
      const colors = this.getColorsForLevel(themeId, level);
      if (colors) {
        result.items[nodeId] = {
          override: {
            shape: {
              style: {
                fill: colors.fill,
                stroke: colors.stroke
              },
              textStyle: {
                color: colors.text
              }
            }
          }
        };
      }
    });
    return result;
  }

  /**
   * 获取主题预览（显示不同层级的颜色）
   * @param {string} themeId 主题ID
   * @returns {Array} 预览数据 [{ level, levelName, colors }, ...]
   */
  getThemePreview(themeId) {
    const theme = this.getThemeById(themeId);
    if (!theme) return [];
    const preview = [];
    const levelNames = {
      0: 'CEO/总裁',
      1: 'VP/副总',
      2: 'Director/总监',
      3: 'Manager/经理'
    };
    Object.keys(theme.levels).forEach(level => {
      const levelNum = parseInt(level);
      preview.push({
        level: levelNum,
        levelName: levelNames[levelNum] || `L${levelNum}`,
        colors: theme.levels[level]
      });
    });
    return preview.sort((a, b) => a.level - b.level);
  }

  /**
   * 设置当前主题
   * @param {string} themeId 主题ID
   */
  setCurrentTheme(themeId) {
    const theme = this.getThemeById(themeId);
    if (theme) {
      this.currentTheme = theme;
    }
  }

  /**
   * 获取当前主题
   * @returns {Object} 当前主题
   */
  getCurrentTheme() {
    return this.currentTheme;
  }
}

