const AxisTypeMap = {
  [AXIS_TYPE.HORIZONTAL_NORMAL]: NormalAxis,
  [AXIS_TYPE.VERTICAL_NORMAL]: NormalAxis
};

/**
 * 获取坐标轴实例
 * @param {string} type 坐标轴类型
 * @returns {Axis} 坐标轴实例
 */
function getAxisInstance(type, ...args) {
  const AxisClass = AxisTypeMap[type];
  if (!AxisClass) {
    throw new Error(`Axis type ${type} not found`);
  }
  return new AxisClass(...args);
}
