class Renderer {
  nodeMap = new Map();
  nodeDataMap = new Map();
  constructor(app) {
    this._ctx = app;
    this.initCommands();
  }
  render() {
    // 保存当前选中的节点ID列表
    const selectedNodeIds = this._getSelectedNodeIds();
    if (this.container) {
      this.container.clear();
    } else {
      this.container = new draw_esm_min_ge();
      this._ctx.canvas.add(this.container);
      this.bindCanvasEvents();
    }
    const nodeUpdateInfo = {
      add: {},
      update: {},
      remove: {}
    };
    const {
      axis,
      nodeStyle,
      nodeList
    } = this._ctx.data;
    const newNodeMap = new Map();
    this.nodeDataMap.clear();
    nodeList.forEach(nodeItem => {
      const nodeInstance = this.nodeMap.get(nodeItem.id);
      if (nodeInstance) {
        nodeUpdateInfo.update[nodeInstance.id] = nodeInstance;
        newNodeMap.set(nodeItem.id, nodeInstance);
        nodeInstance.setData(nodeItem);
        nodeInstance.buildNodeConfig();
      } else {
        const newNode = getNodeInstance(nodeStyle.type || nodeItem.type, {
          ctx: this._ctx,
          data: nodeItem
        });
        nodeUpdateInfo.add[newNode.id] = newNode;
        newNodeMap.set(newNode.id, newNode);
      }
      this.nodeDataMap.set(nodeItem.id, nodeItem);
    });
    const {
      add,
      update,
      remove
    } = nodeUpdateInfo;
    this.nodeMap.forEach(node => {
      if (!add[node.id] && !update[node.id]) {
        remove[node.id] = node;
      }
    });
    Object.values(remove).forEach(node => node.destroy());
    this.nodeMap.clear();
    this.nodeMap = newNodeMap;
    this.axisInstance = getAxisInstance(axis.type, {
      ctx: this._ctx,
      data: axis
    });
    this._calcRenderContainerBounds();
    this.axisInstance.render();
    // 渲染完成后恢复选中状态
    if (!this._ctx.opts.readonly) {
      this._restoreSelection(selectedNodeIds);
    }
  }
  _calcRenderContainerBounds() {
    const {
      padding: paddingArr
    } = this._ctx.opts;
    this._ctx.app.tree.nextRender(() => {
      if (!this.container) {
        return;
      }
      const renderContainerBounds = this.container.renderBounds;
      this.container.x = paddingArr[3] - renderContainerBounds.x;
      this.container.y = paddingArr[0] - renderContainerBounds.y;
      const fitWidth = paddingArr[3] + renderContainerBounds.width + paddingArr[1];
      const fitHeight = paddingArr[0] + renderContainerBounds.height + paddingArr[2];
      this._ctx.emit(constant_EVENT_TYPE.CANVAS_FIT_BOUNDS_CHANGE, {
        width: fitWidth,
        height: fitHeight
      });
    });
  }

  /**
   * 获取当前选中的节点ID列表
   * @returns {Array} 选中的节点ID数组
   */
  _getSelectedNodeIds() {
    try {
      const selectedNodes = this._ctx.getSelectedNodes();
      return selectedNodes.map(node => node.id);
    } catch (error) {
      console.warn('获取选中节点ID失败:', error);
      return [];
    }
  }

  /**
   * 恢复节点的选中状态
   * @param {Array} selectedNodeIds 要恢复选中的节点ID列表
   */
  _restoreSelection(selectedNodeIds) {
    if (!selectedNodeIds || selectedNodeIds.length === 0) {
      return;
    }
    requestAnimationFrame(() => () => {
      const nodesToSelect = [];
      selectedNodeIds.forEach(nodeId => {
        const node = this.nodeMap.get(nodeId);
        if (node && node.group && node.group.editable) {
          nodesToSelect.push(node.group);
        }
      });
      if (nodesToSelect.length > 0) {
        // 使用选择管理器恢复选中状态
        this._ctx.app.editor.select(nodesToSelect);
        this._ctx.app.canvas.view.focus();
        // 触发选择变化事件，确保UI状态同步
        this._ctx.selectionManager.handleSelect({
          target: nodesToSelect[0],
          list: nodesToSelect
        });
      }
    });
  }
  getNodeData(nodeID) {
    return this.nodeDataMap.get(nodeID);
  }
  initCommands() {
    this._ctx.on(constant_COMMAND_TYPE.MOVE_AXIS_SEGMENT, ({
      fromIndex,
      toIndex
    }) => {
      this._ctx.executeCommand({
        forward: {
          action: constant_COMMAND_TYPE.MOVE_AXIS_SEGMENT,
          payload: {
            fromIndex,
            toIndex
          }
        },
        backward: {
          action: constant_COMMAND_TYPE.MOVE_AXIS_SEGMENT,
          payload: {
            fromIndex: toIndex,
            toIndex: fromIndex
          }
        }
      });
    });
    this._ctx.on(constant_COMMAND_TYPE.UPDATE_NODE, updateData => {
      const {
        id,
        content,
        origin
      } = updateData;
      const processUndefined = obj => {
        if (!obj || typeof obj !== 'object') return obj;
        const newObj = Array.isArray(obj) ? [...obj] : {
          ...obj
        };
        Object.keys(newObj).forEach(key => {
          if (newObj[key] === undefined) {
            newObj[key] = this._ctx.constructor.DELETE_SENTINEL;
          } else if (typeof newObj[key] === 'object' && newObj[key] !== null) {
            newObj[key] = processUndefined(newObj[key]);
          }
        });
        return newObj;
      };
      const backwardContent = processUndefined(origin);
      this._ctx.executeCommand({
        forward: {
          action: constant_COMMAND_TYPE.UPDATE_NODE,
          payload: {
            id,
            content
          }
        },
        backward: {
          action: constant_COMMAND_TYPE.UPDATE_NODE,
          payload: {
            id,
            content: backwardContent
          }
        }
      });
    });
  }
  bindCanvasEvents() {
    this.container?.on(core_esm_min_nt.DRAG, (...args) => {
      this._ctx.emit(constant_EVENT_TYPE.APP_DRAG, ...args);
    });
    this.container?.on(core_esm_min_nt.END, (...args) => {
      this._ctx.emit(constant_EVENT_TYPE.APP_DRAG_END, ...args);
    });
  }
}
