/**
 * 节点选择管理器 - 基于 leafer-ui editor 原生选中功能
 * 负责管理节点的选择状态，提供统一的选择API和事件
 */
class SelectionManager {
  constructor(_ctx) {
    this._ctx = _ctx;
    this.app = this._ctx.app;
    this.init();
  }

  /**
   * 初始化选择管理器
   */
  init() {
    this.bindEditorEvents();
  }

  /**
   * 绑定编辑器事件
   */
  bindEditorEvents() {
    // 监听编辑器的选中事件
    // this.app.editor.on(EditorEvent.SELECT, (e) => {
    //   this.handleSelect(e);
    // });
    this._ctx.on(constant_EVENT_TYPE.APP_EDITOR_SELECT, e => {
      this.handleSelect(e);
    });
    this._ctx.on(constant_EVENT_TYPE.POINT_EVENT_UP, () => {
      if (this.scaleNode) {
        const newSize = {
          width: this.scaleNode.group.width,
          height: this.scaleNode.group.height
        };
        const oldSize = {
          width: this.scaleNode._data.override?.width,
          height: this.scaleNode._data.override?.height
        };
        this._ctx.emit(constant_COMMAND_TYPE.UPDATE_NODE, {
          id: this.scaleNode.id,
          content: {
            override: newSize
          },
          origin: {
            override: oldSize
          }
        });
        this.scaleNode._fixedTopLeft = null;
        this.scaleNode = null;
      }
    });

    // 监听编辑器的缩放事件，进行尺寸限制
    this._ctx.on(constant_EVENT_TYPE.APP_EDITOR_SCALE, e => {
      this.handleEditorResize(e);
    });
  }

  /**
   * 处理编辑器缩放事件，进行尺寸限制
   */
  handleEditorResize(e) {
    const element = e.target;
    if (!element) return;
    const node = this.findNodeByElement(element);
    if (!node) return;
    this.scaleNode = node;
    const {
      scaleX,
      scaleY
    } = e;
    if (!node._fixedTopLeft) {
      const b = node.group.worldBoxBounds;
      node._fixedTopLeft = {
        x: b.x,
        y: b.y
      };
    }
    if (scaleX !== 1) {
      node.rerender({
        width: node.group.width,
        height: node.group.height
      });
    } else if (scaleY !== 1) {
      node.rerender({
        width: node.group.width,
        height: node.group.height
      });
    }
  }

  /**
   * 处理编辑器选中事件
   * 包括：选中新元素、取消选中、切换选中等情况
   */
  handleSelect() {
    // 触发选择变化事件
    const selectedNodes = this.getSelectedNodes();
    this._ctx.emit(constant_EVENT_TYPE.SELECTION_CHANGE, {
      selectedList: selectedNodes
    });
  }

  /**
   * 根据 leafer 元素查找对应的节点实例
   */
  findNodeByElement(element) {
    return this._ctx.renderer.nodeMap.get(element.data.nodeId);
  }

  /**
   * 选中节点（单选）
   */
  selectNode(nodeId) {
    if (!nodeId) return;
    const node = this._ctx.renderer.nodeMap.get(nodeId);
    if (!node || !node.group) return;

    // 使用 editor 的原生选中功能
    this.app.editor.select(node.group);
    this.app.canvas.view.focus(); // 聚焦画布
  }

  /**
   * 清除所有选择
   */
  clearSelection() {
    this.app.editor.cancel();
  }

  /**
   * 获取选中的节点列表
   */
  getSelectedNodes() {
    const selectedElements = this.app.editor.list;
    const selectedNodes = [];
    selectedElements.forEach(element => {
      const node = this.findNodeByElement(element);
      if (node) {
        selectedNodes.push(node);
      }
    });
    return selectedNodes;
  }

  /**
   * 销毁选择管理器
   */
  destroy() {
    this.app.editor?.off(editor_esm_min_K.SELECT);
    this.app.editor?.off(editor_esm_min_qt.SCALE);
    // 清理引用
    this.app.editor = null;
    this._ctx = null;
    this.selectedNodes = [];
  }
}
