function getThemeDataById(id) {
  const allThemes = [...ThemeList.horizontal.list, ...ThemeList.vertical.list];
  const theme = allThemes.find(item => item.id === id);
  return theme ? theme.data : null;
}
function getDocumentDataByTheme(data) {
  data.nodeList = getBaseNodeList();
  data.axis.axisSegmentList = getBaseAxisSegmentList();
  return data;
}
