const ThemeThumbnailMap = new Map();
class LayoutSelectPanel {
  themeIdMap = new Map();
  constructor(options = {}) {
    this.onSelect = options.onSelect;
  }
  render(container) {
    this.renderLayoutSelectPanel(container);
    this.initScript(container);
  }
  renderLayoutSelectPanel(container) {
    const panel = document.createElement('div');
    this.panel = panel;
    panel.id = 'layout-select-panel';
    container.appendChild(panel);
    const title = document.createElement('div');
    title.className = 'layout-select-panel-title';
    title.innerText = '智能布局';
    panel.appendChild(title);
    const tabsContainer = document.createElement('div');
    tabsContainer.className = 'layout-tabs-container';
    panel.appendChild(tabsContainer);
    this.themeIdMap.clear();
    const tabs = Object.keys(ThemeList).map(key => {
      const theme = ThemeList[key];
      return {
        id: key,
        title: theme.title,
        content: this.renderList(theme.list)
      };
    });
    new Tabs({
      container: tabsContainer,
      tabs
    });
  }
  renderList(list) {
    const listWrap = document.createElement('div');
    listWrap.className = 'image-select-list';
    listWrap.innerHTML = list.map(item => {
      this.themeIdMap.set(item.id, item);
      return `<div class="image-select-item" data-themeId="${item.id}"><img class="image-select-img" src="" alt="" ></div>`;
    }).join('');
    list.forEach(item => {
      this.getThemeThumbnail(item).then(imgUrl => {
        listWrap.querySelector(`[data-themeId="${item.id}"]`).querySelector('img').setAttribute('src', imgUrl);
      });
    });
    return listWrap;
  }
  async getThemeThumbnail(data) {
    const img = ThemeThumbnailMap.get(data.id);
    if (img) {
      return img;
    } else {
      const timeline = new Timeline_Timeline({
        readonly: true
      });
      timeline.setFullData(getDocumentDataByTheme(data.data));
      return timeline.export().then(res => {
        ThemeThumbnailMap.set(data.id, res.data);
        timeline.destroy();
        return res.data;
      });
    }
  }
  initScript(container) {
    const layoutSelectPanel = container.querySelector('#layout-select-panel');
    // 阻止 mousedown 冒泡，防止点击面板时触发 dropdown 的自动关闭（如果它是基于 mousedown 的）
    layoutSelectPanel.addEventListener('mousedown', e => {
      e.stopPropagation();
    });
    layoutSelectPanel.addEventListener('mouseup', e => {
      e.stopPropagation();
    });
    layoutSelectPanel.addEventListener('click', e => {
      e.stopPropagation();
    });
    layoutSelectPanel.addEventListener('click', e => {
      e.stopPropagation();
      const target = e.target;
      if (target.closest('.image-select-item')) {
        const layoutSelectItems = layoutSelectPanel.querySelectorAll('.image-select-item');
        layoutSelectItems.forEach(item => {
          if (item.contains(target)) {
            item.classList.add('active');
            const themeId = item.getAttribute('data-themeId');
            const config = this.themeIdMap.get(themeId);
            delete config.data.nodeList;
            delete config.data.axis.axisSegmentList;
            this.onSelect?.(config);
          } else {
            item.classList.remove('active');
          }
        });
      }
    });
  }
  select(id) {
    this.panel.querySelectorAll('.image-select-item').forEach(item => {
      if (item.getAttribute('data-themeId') === id) {
        item.classList.add('active');
      } else {
        item.classList.remove('active');
      }
    });
  }
}
