/**
 * Radio 单选框组件
 * 支持常规单选框和按钮形式，以及 RadioGroup 统一管理
 */

/**
 * 基础 Radio 组件
 */

class Radio_Radio {
  /**
   * 构造函数
   * @param {Object} options 配置选项
   * @param {HTMLElement|string} options.container 容器元素或选择器
   * @param {string} options.value 单选框的值
   * @param {string} options.label 显示文本
   * @param {boolean} options.checked 是否选中
   * @param {boolean} options.disabled 是否禁用
   * @param {string} options.size 尺寸 'small' | 'middle' | 'large'
   * @param {string} options.type 类型 'radio' | 'button'
   * @param {string} options.name 表单名称
   * @param {Function} options.onChange 值变化回调
   */
  constructor(options = {}) {
    this.container = this._getElement(options.container);
    this.value = options.value || '';
    this.label = options.label || '';
    this.checked = options.checked || false;
    this.disabled = options.disabled || false;
    this.size = options.size || 'middle';
    this.type = options.type || 'radio';
    this.name = options.name || '';
    this.onChange = options.onChange || (() => {});
    this.radioElement = null;
    this.labelElement = null;
    this.wrapperElement = null;
    this.group = null; // 所属的 RadioGroup

    this._init();
  }

  /**
   * 初始化组件
   */
  _init() {
    if (!this.container) {
      throw new Error('Radio: 容器元素不存在');
    }
    this.container.classList.add('smart-radio-wrapper');
    this._createStructure();
    this._bindEvents();
    this._updateState();
  }

  /**
   * 创建DOM结构
   */
  _createStructure() {
    // 创建包装器
    this.wrapperElement = document.createElement('label');
    this.wrapperElement.className = this._getWrapperClass();
    if (this.type === 'button') {
      // 按钮形式
      this.radioElement = document.createElement('input');
      this.radioElement.type = 'radio';
      this.radioElement.value = this.value;
      this.radioElement.name = this.name;
      this.radioElement.className = 'radio-button-input';
      this.labelElement = document.createElement('span');
      this.labelElement.className = 'radio-button-inner';
      this.labelElement.textContent = this.label;
      this.wrapperElement.appendChild(this.radioElement);
      this.wrapperElement.appendChild(this.labelElement);
    } else {
      // 常规形式 - 需要创建 radio-inner 元素
      const radioInner = document.createElement('span');
      radioInner.className = 'radio-inner';
      this.radioElement = document.createElement('input');
      this.radioElement.type = 'radio';
      this.radioElement.value = this.value;
      this.radioElement.name = this.name;
      this.radioElement.className = 'radio-input';

      // 创建标签
      if (this.label) {
        this.labelElement = document.createElement('span');
        this.labelElement.className = 'radio-label';
        this.labelElement.textContent = this.label;
      }

      // 组装DOM
      this.wrapperElement.appendChild(radioInner);
      this.wrapperElement.appendChild(this.radioElement);
      if (this.labelElement) {
        this.wrapperElement.appendChild(this.labelElement);
      }
    }
    this.container.appendChild(this.wrapperElement);
  }

  /**
   * 获取包装器样式类
   */
  _getWrapperClass() {
    const baseClass = this.type === 'button' ? 'radio-button-wrapper' : 'radio-wrapper';
    const classes = [baseClass];
    if (this.size !== 'middle') {
      classes.push(`${baseClass}-${this.size}`);
    }
    if (this.checked) {
      classes.push(`${baseClass}-checked`);
    }
    if (this.disabled) {
      classes.push(`${baseClass}-disabled`);
    }
    return classes.join(' ');
  }

  /**
   * 绑定事件
   */
  _bindEvents() {
    if (this.radioElement) {
      this.radioElement.addEventListener('change', e => {
        if (!this.disabled) {
          this.setChecked(e.target.checked);
          if (this.group) {
            this.group._handleRadioChange(this);
          } else {
            this.onChange(this.value, this);
          }
        }
      });
    }
  }

  /**
   * 更新状态
   */
  _updateState() {
    if (this.radioElement) {
      this.radioElement.checked = this.checked;
      this.radioElement.disabled = this.disabled;
    }
    if (this.wrapperElement) {
      this.wrapperElement.className = this._getWrapperClass();
    }
  }

  /**
   * 设置选中状态
   */
  setChecked(checked) {
    this.checked = checked;
    this._updateState();
  }

  /**
   * 设置禁用状态
   */
  setDisabled(disabled) {
    this.disabled = disabled;
    this._updateState();
  }

  /**
   * 设置标签文本
   */
  setLabel(label) {
    this.label = label;
    if (this.labelElement) {
      this.labelElement.textContent = label;
    }
  }

  /**
   * 获取DOM元素
   */
  _getElement(selector) {
    if (typeof selector === 'string') {
      return document.querySelector(selector);
    }
    return selector;
  }

  /**
   * 销毁组件
   */
  destroy() {
    if (this.wrapperElement && this.wrapperElement.parentNode) {
      this.wrapperElement.parentNode.removeChild(this.wrapperElement);
    }
    this.radioElement = null;
    this.labelElement = null;
    this.wrapperElement = null;
  }
}

/**
 * RadioGroup 组件
 */
class RadioGroup {
  /**
   * 构造函数
   * @param {Object} options 配置选项
   * @param {HTMLElement|string} options.container 容器元素或选择器
   * @param {Array} options.options 选项数组
   * @param {string} options.value 当前值
   * @param {boolean} options.disabled 是否禁用
   * @param {string} options.size 尺寸
   * @param {string} options.type 类型
   * @param {string} options.direction 方向 'horizontal' | 'vertical'
   * @param {string} options.name 表单名称
   * @param {Function} options.onChange 值变化回调
   * @param {string} options.className 自定义类名
   */
  constructor(options = {}) {
    this.container = this._getElement(options.container);
    this.options = options.options || [];
    this.value = options.value || '';
    this.disabled = options.disabled || false;
    this.size = options.size || 'middle';
    this.type = options.type || 'radio';
    this.direction = options.direction || 'horizontal';
    this.name = options.name || `radio-group-${Date.now()}`;
    this.onChange = options.onChange || (() => {});
    this.className = options.className || '';
    this.groupElement = null;
    this.radios = [];
    this._init();
  }

  /**
   * 初始化组件
   */
  _init() {
    if (!this.container) {
      throw new Error('RadioGroup: 容器元素不存在');
    }
    this.container.classList.add('smart-radio-wrapper');
    this._createStructure();
    this._createRadios();
  }

  /**
   * 创建DOM结构
   */
  _createStructure() {
    this.groupElement = document.createElement('div');
    this.groupElement.className = this._getGroupClass();
    this.container.appendChild(this.groupElement);
  }

  /**
   * 获取组样式类
   */
  _getGroupClass() {
    const baseClass = this.type === 'button' ? 'radio-group-button' : 'radio-group';
    const classes = [baseClass];
    if (this.className) {
      classes.push(this.className);
    }
    if (this.size !== 'middle') {
      classes.push(`${baseClass}-${this.size}`);
    }
    if (this.direction === 'vertical') {
      classes.push(`${baseClass}-vertical`);
    }
    return classes.join(' ');
  }

  /**
   * 创建单选框
   */
  _createRadios() {
    this.options.forEach(option => {
      const radioContainer = document.createElement('div');
      radioContainer.className = 'radio-item';
      this.groupElement.appendChild(radioContainer);
      const radio = new Radio_Radio({
        container: radioContainer,
        value: option.value,
        label: option.label,
        checked: option.value === this.value,
        disabled: this.disabled || option.disabled,
        size: this.size,
        type: this.type,
        name: this.name,
        onChange: () => {} // 由 group 统一处理
      });
      radio.group = this;
      this.radios.push(radio);
    });
  }

  /**
   * 处理单选框变化
   */
  _handleRadioChange(changedRadio) {
    // 取消其他单选框的选中状态
    this.radios.forEach(radio => {
      if (radio !== changedRadio) {
        radio.setChecked(false);
      }
    });

    // 更新当前值
    this.value = changedRadio.value;
    this.onChange(this.value, changedRadio);
  }

  /**
   * 设置值
   */
  setValue(value) {
    this.value = value;
    this.radios.forEach(radio => {
      radio.setChecked(radio.value === value);
    });
  }

  /**
   * 获取值
   */
  getValue() {
    return this.value;
  }

  /**
   * 设置禁用状态
   */
  setDisabled(disabled) {
    this.disabled = disabled;
    this.radios.forEach(radio => {
      radio.setDisabled(disabled);
    });
  }

  /**
   * 添加选项
   */
  addOption(option) {
    this.options.push(option);
    const radioContainer = document.createElement('div');
    radioContainer.className = 'radio-item';
    this.groupElement.appendChild(radioContainer);
    const radio = new Radio_Radio({
      container: radioContainer,
      value: option.value,
      label: option.label,
      checked: option.value === this.value,
      disabled: this.disabled || option.disabled,
      size: this.size,
      type: this.type,
      name: this.name,
      onChange: () => {} // 由 group 统一处理
    });
    radio.group = this;
    this.radios.push(radio);
  }

  /**
   * 移除选项
   */
  removeOption(value) {
    const index = this.options.findIndex(option => option.value === value);
    if (index > -1) {
      this.options.splice(index, 1);
      const radio = this.radios[index];
      if (radio) {
        radio.destroy();
        this.radios.splice(index, 1);
      }
    }
  }

  /**
   * 获取DOM元素
   */
  _getElement(selector) {
    if (typeof selector === 'string') {
      return document.querySelector(selector);
    }
    return selector;
  }

  /**
   * 销毁组件
   */
  destroy() {
    this.radios.forEach(radio => radio.destroy());
    if (this.groupElement && this.groupElement.parentNode) {
      this.groupElement.parentNode.removeChild(this.groupElement);
    }
  }
}

