/**
 * 根据拟合出的最佳参数，将任意 hex 颜色转换为目标风格的亮、柔、饱和色
 *
 * 参数说明（均已自动拟合为最优值）：
 *   t = 0.30             // 混白比例（RGB 空间中向白色靠近 30%）
 *   L_boost = 0.04       // HSL 亮度补偿（使颜色更柔亮）
 *   sat_mul = 1.30       // 饱和度增强比例（让颜色更鲜，不会发灰）
 *
 * 转换流程：
 *   1. hex → RGB
 *   2. RGB 混白（向 255,255,255 推进）
 *   3. RGB → HSL
 *   4. L += 0.04，S *= 1.30
 *   5. HSL → RGB → hex
 */
function convertColor(hexColor, t = 0.3, L_boost = 0.04, sat_mul = 1.3) {
  /* -------------------- Step1：RGB 向白色混合 -------------------- */
  const rgb = (0,color/* hexToRgb */.E2)(hexColor);
  const mixWhite = v => Math.round(v + t * (255 - v));
  const r1 = mixWhite(rgb.r);
  const g1 = mixWhite(rgb.g);
  const b1 = mixWhite(rgb.b);
  /* -------------------- Step2：转换到 HSL 调整亮度/饱和度 -------------------- */

  let {
    h,
    s,
    l
  } = (0,color/* rgbToHsl */.K6)({
    r: r1,
    g: g1,
    b: b1
  });

  // 亮度增强
  l = Math.min(1, l + L_boost);

  // 饱和度增强（拟合出最接近样例的 1.30）
  s = Math.min(1, s * sat_mul);

  /* -------------------- Step3：HSL → RGB → hex -------------------- */

  const {
    r,
    g,
    b
  } = (0,color/* hslToRgb */.YL)({
    h,
    s,
    l
  });
  return (0,color/* rgbToHex */.Ob)({
    r,
    g,
    b
  });
}
