class ThemeManager {
  constructor() {
    if (ThemeManager._instance) return ThemeManager._instance;
    ThemeManager._instance = this;
    this.themes = new Map();
  }

  /**
   * 注册 / 覆盖主题
   * @param {string} name 英文名称（唯一 ID）
   * @param {*} config palette / rules / meta
   */
  registerTheme(name, {
    meta = {},
    palette = {},
    rules = {}
  }) {
    this.themes.set(name, {
      meta,
      palette,
      rules
    });
  }

  /**
   * 获取主题（带规则计算）
   */
  getTheme(name) {
    const theme = this.themes.get(name);
    if (!theme) return null;
    const {
      palette,
      rules,
      meta
    } = theme;
    const computed = {};
    for (const key in rules) {
      const rule = rules[key];
      computed[key] = typeof rule === 'function' ? rule({
        palette
      }) : rule;
    }
    return {
      palette,
      computed,
      meta
    };
  }

  /**
   * 修改单个 palette key
   */
  setPaletteValue(name, key, value) {
    const theme = this.themes.get(name);
    if (!theme) return;
    theme.palette[key] = value;
  }

  /**
   * 修改全部 palette （部分或全部）
   */
  updatePalette(name, newPalette, overwrite = false) {
    const theme = this.themes.get(name);
    if (!theme) return;
    if (overwrite) {
      theme.palette = {
        ...newPalette
      };
    } else {
      Object.assign(theme.palette, newPalette);
    }
  }

  /**
   * 修改 handDrawnStyle
   */
  updateHandDrawnStyle(name, newStyle = {}) {
    const theme = this.themes.get(name);
    let graphStyle = theme?.rules?.nodeStyle?.graph?.handDrawnStyle;
    if (!graphStyle) return;
    theme.rules.nodeStyle.graph.handDrawnStyle = Object.assign({}, graphStyle, newStyle);
  }
  getHandDrawnStyle(name) {
    const theme = this.themes.get(name);
    const graphStyle = theme?.rules?.nodeStyle?.graph?.handDrawnStyle;
    return Object.assign({}, graphStyle || {});
  }

  /**
   * 获取主题列表（包含英文名和中文名）
   */
  getThemeList() {
    return [...this.themes.entries()].map(([key, theme]) => ({
      name: key,
      nameZH: theme.meta?.nameZH || key
    }));
  }
}
