class HorizontalList extends BaseLayout {
  getList(targetNodeList) {
    const nodeList = targetNodeList || this._ctx.getNodeList();
    const nodeListLength = nodeList.length;
    nodeList.forEach(node => {
      node.render();
    });
    const {
      layoutOptions: {
        flowAlign = 'center',
        padding = 10,
        flowWrap = true,
        gap = {
          x: 20,
          y: 20
        },
        flow,
        isReversal = false
      } = {}
    } = this;
    const flowList = new FlowList({
      options: {
        gap,
        flowAlign,
        flowWrap,
        padding,
        width: this.layoutOptions.width,
        height: this.layoutOptions.height,
        flow
      },
      elements: nodeList.map((item, index) => {
        let el = item.getElement();
        if (isReversal) {
          el.zIndex = nodeListLength - index;
        }
        return el;
      })
    });
    this.group = flowList.getElement();
    return this.group;
  }
  render() {
    return this.getList();
  }
  destroy() {
    this.group?.destroy();
  }
}
