function normalizeGap(options = {}) {
  const {
    gap,
    rowGap,
    columnGap
  } = options;
  if (typeof gap === 'number') {
    return {
      x: gap,
      y: gap
    };
  }
  if (gap && typeof gap === 'object') {
    return {
      x: gap.x ?? 0,
      y: gap.y ?? 0
    };
  }
  return {
    x: columnGap ?? 0,
    y: rowGap ?? 0
  };
}
