class TitleNode extends node_Node_Node {
  render(style = {}) {
    this.group.clear();
    const nodeStyle = this.style.getStyle();
    const title = new RichText({
      text: this._data.title,
      style: {
        ...nodeStyle.title,
        ...style
      },
      onChange: (text, modifyStyle) => {
        const newData = {
          title: text
        };
        if (modifyStyle && Object.keys(modifyStyle).length) {
          newData.override = {
            title: {
              ...modifyStyle
            }
          };
        }
        this.updateNodeData(newData);
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      id: `node-title-${this.id}`
    });
    this.group.data = {
      ...this.group.data,
      includeRichTextId: `node-title-${this.id}`
    };
    this.group.add(title.getElement());
  }
}
