/**
 * 获取智能圆形布局的节点位置和对齐方式
 * @param {Object} params
 * @param {Object} params.center - 圆心 {x, y}
 * @param {number} params.angle - 角度 (弧度)
 * @param {number} params.radius - 图标中心所在的圆半径
 * @param {number|Object} params.iconSize - 图标尺寸 (数字或 {width, height})
 * @param {Object} params.textBounds - 文本节点包围盒 {width, height}
 * @param {number} [params.spacing=24] - 图标与文本的间距
 * @param {Object} [params.options] - 配置选项
 * @param {number} [params.options.centerAngle=270] - 中心对齐的角度 (度数)，默认 270 (上方)
 * @param {number} [params.options.threshold=5] - 中心对齐的角度容差 (度数)
 * @param {string|Function} [params.options.verticalAlign='middle'] - 垂直对齐策略
 *   - 'middle': 垂直居中 (默认)
 *   - 'top': 顶部对齐 (文本顶 = 图标顶)
 *   - 'bottom': 底部对齐 (文本底 = 图标底)
 *   - Function: (info) => y
 * @returns {Object} { x, y, align, p }
 */
function getSmartCircularNodeStyle(params) {
  const {
    center,
    angle,
    radius,
    iconSize,
    textBounds,
    spacing = 24,
    options = {}
  } = params;
  const {
    centerAngle = 270,
    threshold = 5,
    verticalAlign = 'middle'
  } = options;
  let deg = angle * 180 / Math.PI;
  // 归一化 deg 到 [0, 360)
  deg = deg % 360;
  if (deg < 0) deg += 360;

  // 计算角度差并归一化到 [-180, 180]
  let diff = deg - centerAngle;
  while (diff <= -180) diff += 360;
  while (diff > 180) diff -= 360;
  const p = {
    x: center.x + radius * Math.cos(angle),
    y: center.y + radius * Math.sin(angle)
  };
  const iconR = (typeof iconSize === 'number' ? iconSize : Math.max(iconSize.width, iconSize.height)) / 2;
  const boundsX = textBounds.x || 0;
  const boundsY = textBounds.y || 0;

  // 1. 确定对齐方式 (Align)
  let align = 'center';
  // Check for Top Center (diff near 0) OR Bottom Center (diff near 180/-180)
  if (Math.abs(diff) < threshold || Math.abs(Math.abs(diff) - 180) < threshold) {
    align = 'center';
  } else if (diff < 0) {
    align = 'right';
  } else {
    align = 'left';
  }

  // 2. 计算 X 坐标
  let x = p.x;
  if (align === 'right') {
    // 文本在左侧，右对齐
    x = p.x - iconR - spacing - textBounds.width - boundsX;
  } else if (align === 'left') {
    // 文本在右侧，左对齐
    x = p.x + iconR + spacing - boundsX;
  } else {
    // 居中
    x = p.x - textBounds.width / 2 - boundsX;
  }

  // 3. 计算 Y 坐标
  let y = p.y;
  if (typeof verticalAlign === 'function') {
    y = verticalAlign({
      deg,
      p,
      iconRadius: iconR,
      textBounds,
      spacing
    });
  } else if (align === 'center') {
    // 中心节点 (Top/Bottom Center)

    // Top Center (around 270)
    if (Math.abs(diff) < threshold) {
      y = p.y - iconR - spacing - textBounds.height - boundsY;
    } else {
      // Bottom Center (around 90)
      // 90度时，diff应为 90 - 270 = -180.
      // 但上面已经归一化diff到[-180, 180]。如果deg=90, diff=-180.
      // 简单的判断：如果在下方 (90 +/- threshold)
      const isBottom = Math.abs(deg - 90) < threshold || Math.abs(deg - 450) < threshold;
      if (isBottom) {
        y = p.y + iconR + spacing - boundsY;
      } else {
        // 其他center情况，默认上方
        y = p.y - iconR - spacing - textBounds.height - boundsY;
      }
    }
  } else {
    // 侧边节点
    if (verticalAlign === 'top') {
      y = p.y - iconR - boundsY;
    } else if (verticalAlign === 'bottom') {
      y = p.y + iconR - textBounds.height - boundsY;
    } else if (verticalAlign === 'smart') {
      // 智能对齐：偏上位置底部对齐，偏下位置顶部对齐
      // 判断是否偏上: [180, 360] (即y <= center.y)
      // 但考虑到视觉习惯，以水平线为界
      // deg 在 (180, 360) 之间为上半圆 (注意y向下为正，sin(180~360) < 0，即上方)
      // deg 在 (0, 180) 之间为下半圆

      const isUpper = deg > 180 && deg < 360;
      if (isUpper) {
        // 上半圆：底部对齐
        y = p.y + iconR - textBounds.height - boundsY;
      } else {
        // 下半圆：顶部对齐
        y = p.y - iconR - boundsY;
      }
    } else {
      // middle
      y = p.y - textBounds.height / 2 - boundsY;
    }
  }
  return {
    x,
    y,
    align,
    p // 返回计算出的锚点(图标中心)，方便调试或后续使用
  };
}
