class PetalGraphics extends SmartGraphics {
  NodeMap = {
    TextDescriptionNode: TextDescriptionNode
  };
  useNodeType = 'TextDescriptionNode';
  config = {
    circleRadius: 80,
    strokeWidth: 2,
    petalRadiusExtend: 34
  };
  constructor(options = {}) {
    super({
      ...options,
      defaultOptions: {
        nodeMinNumber: 3,
        nodeMaxNumber: 8
      },
      defaultData: {
        nodeStyle: {
          title: {
            fontSize: 20,
            textAlign: 'center',
            maxWidth: 260
          },
          description: {
            fontSize: 15,
            textAlign: 'center',
            maxWidth: 260
          },
          icon: {
            iconSize: {
              width: 48,
              height: 48
            }
          }
        }
      }
    });
  }
  render() {
    super.render();
    const data = this.data;
    let graphicsTitle;
    if (data.title?.show) {
      graphicsTitle = new RichText({
        ...data.title,
        onChange: text => {
          this.updateTitle(text);
        },
        onStyleChange: modifyStyle => {
          this.updateTitle(undefined, modifyStyle);
        },
        id: `graph-title`,
        editable: true,
        customData: {
          entityType: ENTITY_TYPE.RICH_TEXT
        }
      });
    }
    this.group = new draw_esm_min_ge();
    // const { width, height } = this.opts;

    let circleRadius = this.config.circleRadius;
    let petalRadius = circleRadius + this.config.petalRadiusExtend;

    // if (width && height) {
    //   const scale = width / 2 / circleRadius;
    //   circleRadius *= scale;
    //   petalRadius *= scale;
    // }

    const cx0 = circleRadius,
      cy0 = circleRadius; // 中心
    const nodeList = this.getNodeList();
    const sum = nodeList.length;
    const circleCenter = {
      x: cx0,
      y: cy0
    };
    for (let i = 0; i < sum; i++) {
      const angle1 = 2 * Math.PI * i / sum;
      const prev = i - 1 < 0 ? sum - 1 : i - 1;
      const angle2 = 2 * Math.PI * prev / sum;

      // 相邻两个圆圆心
      const c1 = {
        x: cx0 + circleRadius * Math.cos(angle1),
        y: cy0 + circleRadius * Math.sin(angle1)
      };
      const c2 = {
        x: cx0 + circleRadius * Math.cos(angle2),
        y: cy0 + circleRadius * Math.sin(angle2)
      };

      // 求两个圆的交点
      const pts = (0,math/* circleIntersection */.qk)(c1, c2, petalRadius);
      if (!pts) continue;
      const [p1, p2] = pts;
      let startPoint = p1;
      let endPoint = p2;
      if ((0,math/* pointDistance2D */.ie)(p1, circleCenter) < (0,math/* pointDistance2D */.ie)(p2, circleCenter)) {
        startPoint = p2;
        endPoint = p1;
      }
      const startDeg1 = (0,math/* getAngleOnCircleDeg */.tG)(startPoint, c1);
      const startDeg2 = (0,math/* getAngleOnCircleDeg */.tG)(endPoint, c2);
      const offsetDeg1 = (0,math/* radiansToDegrees */.nv)((0,math/* arcAngleBetweenPoints */.xu)(p1, p2, c1, true));
      const offsetDeg2 = (0,math/* radiansToDegrees */.nv)((0,math/* arcAngleBetweenPoints */.xu)(p1, p2, c2));
      const petal = new draw_esm_min_hi({
        fill: this._getFillColor(i),
        strokeWidth: 2,
        stroke: this._getStrokeColor(i)
      });
      // 构造 Pen 路径
      const pen = petal.pen;
      pen.moveTo(startPoint.x, startPoint.y);
      pen.arc(c1.x, c1.y, petalRadius, startDeg1, startDeg1 + offsetDeg1);
      pen.arc(c2.x, c2.y, petalRadius, startDeg2, startDeg2 - offsetDeg2, true); // 弧2
      const handDrawnStyle = this._getHandDrawnStye(i);
      const g = new hand_drawn_shape({
        fill: this._getFillColor(i),
        strokeWidth: 2,
        stroke: this._getStrokeColor(i),
        path: petal.getPathString(true),
        shapeClass: draw_esm_min_hi,
        ...handDrawnStyle
      });
      if (handDrawnStyle.handDrawn) {
        petal.fill = 'transparent';
        petal.stroke = 'transparent';
        g.add(petal);
      }
      const canSelectElement = g.children[g.children.length - 1];
      canSelectElement.editConfig = {
        // selectedStyle: { stroke: 'transparent' },
        rect: {
          stroke: 'transparent'
        }
      };
      canSelectElement.data = {
        entityType: ENTITY_TYPE.NODE_GRAPH,
        nodeId: nodeList[i].id
      };
      canSelectElement.editable = true;
      canSelectElement.id = `node-graph-${nodeList[i].id}`;
      this.group.addAt(g, 0);
      const icon = this._renderIcon(i);
      const iconPos = this.computePetalIcon(c2, c1, petalRadius);
      icon.x = iconPos.x - icon.worldBoxBounds.width / 2;
      icon.y = iconPos.y - icon.worldBoxBounds.height / 2;
      this.group.add(icon);
    }
    for (let i = 0; i < sum; i++) {
      const textNode = nodeList[i];
      this.group.add(textNode.group);
      const midDeg = 360 / sum * i + 1;
      let side = 'center';
      if (midDeg > 295 || midDeg < 65) {
        side = 'right';
      } else if (midDeg < 245 && midDeg > 115) {
        side = 'left';
      }
      if (side !== 'center') {
        textNode.render({
          textAlign: side === 'right' ? 'left' : 'right'
        });
      } else {
        textNode.render();
      }
      const textPos = (0,math/* getElementPosAroundCircle */.sX)(textNode.getBounds(), cx0, cy0, petalRadius + circleRadius + 20, midDeg);
      textNode.group.x = textPos.x;
      textNode.group.y = textPos.y;
    }
    if (graphicsTitle) {
      const flow = new flow_esm_min_m({
        flow: 'y',
        flowAlign: 'center',
        gap: 50,
        children: [graphicsTitle.getElement(), this.group]
      });
      this.renderContainer.add(flow);
    } else {
      this.renderContainer.add(this.group);
    }
  }
  _getFillColor(i) {
    const nodeList = this.getNodeList();
    return nodeList[i].style.getStyle().graph.color[0].fill[0];
  }
  _getHandDrawnStye(i) {
    const nodeList = this.getNodeList();
    const graphStyle = nodeList[i].style.getStyle().graph;
    return {
      handDrawn: graphStyle.handDrawn,
      handDrawnStyle: graphStyle.handDrawnStyle
    };
  }
  _getStrokeColor(i) {
    const nodeList = this.getNodeList();
    return nodeList[i].style.getStyle().graph.color[0].stroke[0];
  }
  _renderIcon(i) {
    const nodeList = this.getNodeList();
    const style = nodeList[i].style.getStyle().icon;
    const src = nodeList[i].data.icon || icon_IconList[i % icon_IconList.length];
    const nodeId = nodeList[i].id;
    const avatar = new Avatar({
      src,
      ...style,
      color: (0,tools/* mergeAlternateArray */.E$)(style.color.stroke, style.color.fill),
      onClick: () => {
        this.emit(src_constant_EVENT_TYPE.NODE_ICON_CLICK, nodeList[i].id, src);
      },
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: nodeId
      },
      id: `node-icon-${nodeId}`
    });
    return avatar.getElement();
  }

  /**
   * 获取花瓣 icon 的视觉中心点
   * 方法：从 c2 指向 c1 做射线，与两个圆分别求交点，取交点中点
   *
   * @param {Object} c1 圆1中心 {x, y}
   * @param {Object} c2 圆2中心 {x, y}
   * @param {number} R  圆半径
   * @returns {Object} {x, y}
   */
  computePetalIcon(c1, c2, R) {
    // direction c2 -> c1（射线方向）
    const dx = c1.x - c2.x;
    const dy = c1.y - c2.y;
    const L = Math.hypot(dx, dy);

    // 避免除 0
    if (L < 1e-6) return {
      x: c1.x,
      y: c1.y
    };
    const ux = dx / L;
    const uy = dy / L;

    // 射线与某圆求交点（取最近的那个）
    function rayCircleIntersection(circle) {
      const ox = c2.x - circle.x;
      const oy = c2.y - circle.y;
      const B = 2 * (ox * ux + oy * uy);
      const C = ox * ox + oy * oy - R * R;
      const disc = B * B - 4 * C;
      if (disc < 0) {
        // 理论上在花瓣里不会发生
        return circle;
      }
      const t = (-B - Math.sqrt(disc)) / 2;
      return {
        x: c2.x + ux * t,
        y: c2.y + uy * t
      };
    }

    // 射线分别与两个圆的交点
    const p1 = rayCircleIntersection(c1);
    const p2 = rayCircleIntersection(c2);

    // 两交点的中点 = 花瓣的视觉中心
    return {
      x: (p1.x + p2.x) / 2,
      y: (p1.y + p2.y) / 2
    };
  }
}
