/**
 * 创建一个带右侧“尖角”的标签形状
 * @param {Object} opts
 * @param {number} opts.width 总宽度（包含尖角）
 * @param {number} opts.height 总高度
 * @param {string} opts.fill 填充色
 * @param {string} opts.stroke 描边色
 * @param {number} opts.strokeWidth 描边宽度
 * @param {number} opts.cornerWidth 右侧尖角的水平宽度（从主矩形到尖端的水平距离）
 * @returns {Group} 包含 Path 的 Group
 */
function createTagShape({
  width = 554,
  height = 86,
  fill = '#E8F9FF',
  stroke = '#1EABDA',
  strokeWidth = 2,
  cornerWidth = 48,
  handDrawn,
  handDrawnStyle // 使用者可调整（SVG 中大约 48）
} = {}) {
  // 为了让 stroke 不会被裁切或改变视觉位置，通常我们会把路径坐标按 strokeWidth/2 做内缩
  const halfStroke = strokeWidth / 2;

  // 主矩形右侧直线到尖角起点的 x 坐标
  // 我们从 1 + halfStroke 开始（模拟你 SVG 中的 M1 位置）
  const leftX = 1 + halfStroke;
  const topY = 1 + halfStroke;
  const rightMostX = width - 1 - halfStroke; // 尖端最右侧
  const notchStartX = rightMostX - cornerWidth; // 尖角起点 x

  // 中心 y，用于尖角顶点
  const midY = height / 2;

  // 底边 y
  const bottomY = height - 1 - halfStroke;

  // 构造路径，等价于 SVG d: M1 1 H505 L553 43 L505 85 H1 V1 Z
  const d = [`M ${leftX} ${topY}`,
  // 起点
  `H ${notchStartX}`,
  // 到尖角起点上边
  `L ${rightMostX} ${midY}`,
  // 到尖角顶点
  `L ${notchStartX} ${bottomY}`,
  // 回到尖角起点下边
  `H ${leftX}`,
  // 回到左侧
  'Z'].join(' ');
  return new hand_drawn_shape({
    stroke,
    strokeWidth,
    fill,
    path: d,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
}
