/**
 * 创建一个带上下折角的矩形标签（角度可调）
 * @param {object} opts
 * @param {number} opts.width 总宽度
 * @param {number} opts.height 总高度
 * @param {number} [opts.foldY] 中间折线的垂直位置（默认 height * 1/3）
 * @param {number} [opts.topAngle] 顶部折角角度（相对水平，度）
 * @param {number} [opts.bottomAngle] 底部折角角度（相对水平，度）
 * @param {number} [opts.topCornerHeight] 顶部折角的垂直高度，用于计算水平宽度
 * @param {number} [opts.bottomCornerHeight] 底部折角的垂直高度
 * @param {string} opts.fill 填充色
 * @param {string} opts.stroke 描边色
 * @param {number} opts.strokeWidth 描边宽度
 */
function createFoldedTag({
  width = 242,
  height = 122,
  foldY,
  topAngle = 60,
  // 顶部折角角度
  bottomAngle = 45,
  // 底部折角角度
  topCornerHeight = 36,
  // 顶部折角高度
  bottomCornerHeight = 36,
  // 底部折角高度
  fill = '#E8F9FF',
  stroke = '#1EABDA',
  strokeWidth = 2,
  handDrawn,
  handDrawnStyle
} = {}) {
  const group = new draw_esm_min_ge();
  const halfStroke = strokeWidth / 2;
  const topY = 1 + halfStroke;
  const bottomY = height - halfStroke;
  const defaultFoldY = Math.round(height / 3);
  const midY = foldY ?? defaultFoldY;
  const leftX = 1 + halfStroke;
  const rightMostX = width - 1 - halfStroke;

  // 用角度计算水平折角宽度
  const deg2rad = deg => deg * Math.PI / 180;
  const topCornerWidth = topCornerHeight / Math.tan(deg2rad(topAngle));
  const bottomCornerWidth = bottomCornerHeight / Math.tan(deg2rad(bottomAngle));
  const topCornerX = leftX + topCornerWidth;
  const bottomCornerX = leftX + bottomCornerWidth;

  // ---- 填充路径 ----
  const fillPath = [
  // 下半块
  `M ${rightMostX} ${bottomY}`, `H ${bottomCornerX}`, `L ${leftX} ${midY}`, `H ${rightMostX}`, `V ${bottomY}`, 'Z',
  // 上半块
  `M ${rightMostX} ${topY}`, `H ${topCornerX}`, `L ${leftX} ${midY}`, `H ${rightMostX}`, `V ${topY}`, 'Z'].join(' ');

  // ---- 描边路径 ----
  const strokePath = [`M ${leftX} ${midY}`, `L ${bottomCornerX} ${bottomY}`, `H ${rightMostX}`, `V ${midY}`, `M ${leftX} ${midY}`, `H ${rightMostX}`, `M ${leftX} ${midY}`, `L ${topCornerX} ${topY}`, `H ${rightMostX}`, `V ${midY}`].join(' ');
  const fillShape = new hand_drawn_shape({
    stroke: 'none',
    fill,
    path: fillPath,
    shapeClass: draw_esm_min_hi,
    fillRule: 'evenodd',
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
  // const fillShape = new Path({
  //   path: fillPath,
  //   fill,
  //   stroke: 'none',
  //   fillRule: 'evenodd',
  // });

  // const strokeShape = new Path({
  //   path: strokePath,
  //   stroke,
  //   strokeWidth,
  //   strokeLinecap: 'round',
  //   strokeLinejoin: 'round',
  //   fill: 'none',
  // });
  const strokeShape = new hand_drawn_shape({
    stroke,
    strokeWidth,
    fill: 'none',
    path: strokePath,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
  group.add(fillShape);
  group.add(strokeShape);
  return group;
}
