class itemIcon extends node_Node_Node {
  constructor(options = {}) {
    super(options);
    this.nodeStyle = this.style.getStyle();
  }
  getLayout() {
    return new flow_esm_min_m({
      flow: 'x',
      width: 240,
      height: 120,
      gap: {
        x: 22,
        y: 0
      },
      padding: [55, 18, 0, 0],
      flowAlign: 'top-right'
    });
  }
  getIcon(SvgIcon, color) {
    let nodeStyle = this.nodeStyle;
    return new Avatar({
      id: this.id,
      src: SvgIcon || this._data.icon,
      ...nodeStyle.icon,
      color: color || (0,tools/* mergeAlternateArray */.E$)(nodeStyle.icon.color.stroke, nodeStyle.icon.color.fill),
      radius: 0,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: this.data.nodeId
      }
    }).getElement();
  }
  bindEvents() {}
  getImage() {
    let icon = this.getIcon();
    icon.hittable = true;
    return icon;
  }
  render() {
    const {
      graph: graphStyle
    } = this.style.getStyle();
    let bg = createFoldedTag({
      fill: graphStyle.color[0].fill[0],
      stroke: graphStyle.color[0].stroke[0],
      foldY: 37,
      ...graphStyle
    });
    const container = this.getLayout();
    let icon = this.getImage();
    container.add(icon);
    this.group.add(bg);
    this.group.add(container);
    this.group.editable = false;
    this.group.hittable = true;
  }
}
