/**
 * 创建复杂标签形状（左侧曲线/半圆 + 可选右下角弧形）
 * @param {Object} opts
 * @param {number} opts.width - 总宽度
 * @param {number} opts.height - 总高度
 * @param {string} opts.fill - 填充色
 * @param {string} opts.stroke - 描边色
 * @param {number} opts.strokeWidth - 描边宽度
 * @param {'curve'|'rect'} opts.needType - 左侧形状类型
 * @param {boolean} opts.bottomRightCurve - 右下角是否为弧形
 * @returns {Group}
 */
function createComplexTagShape({
  width = 122,
  height = 86,
  fill = 'none',
  stroke = '#3CC583',
  strokeWidth = 2,
  needType = 'curve',
  bottomRightCurve = false,
  needBottom = true,
  handDrawn,
  handDrawnStyle
} = {}) {
  const halfStroke = strokeWidth / 2;
  const leftX = halfStroke;
  const rightX = width - halfStroke;
  const topY = halfStroke;
  const bottomY = height - halfStroke;
  const ky = height / 86;
  const curveFactor = Math.max(1, ky);
  let d;
  if (needType === 'curve') {
    // 左侧曲线
    d = [`M ${leftX} ${bottomY / 2}`, `V ${bottomY / 2 - 1 * ky}`, `C ${leftX + 0.2679 * curveFactor} ${bottomY - 20.0344 * curveFactor}, ${19.968 * curveFactor} ${bottomY}, ${42.9971} ${bottomY}`].join(' ');
    if (bottomRightCurve) {
      // 右下角大弧形
      const arcWidth = 45; // 弧形宽度
      const arcHeight = 45; // 弧形高度
      d += ` L ${rightX - arcWidth} ${bottomY} C ${rightX - arcWidth / 2} ${bottomY}, ${rightX} ${bottomY - arcHeight / 2}, ${rightX} ${bottomY - arcHeight}`;
    } else {
      if (needBottom) {
        d += ` L ${rightX} ${bottomY}`;
      } else {
        d += ` M ${rightX} ${bottomY}`;
      }
    }

    // 上边和闭合
    d += ` L ${rightX} ${topY} H ${42.9971} C ${19.968 * curveFactor} ${topY}, ${1.2679 * curveFactor} ${20}, ${leftX} ${bottomY / 2 - 1}`;
  } else {
    // 左侧矩形半圆
    const arcRadius = 42;
    d = [`M ${leftX + arcRadius} ${topY}`, `C ${leftX + arcRadius / 2} ${topY}, ${leftX} ${topY + arcRadius / 2}, ${leftX} ${topY + arcRadius}`, `L ${leftX} ${bottomY - arcRadius}`, `C ${leftX} ${bottomY - arcRadius / 2}, ${leftX + arcRadius / 2} ${bottomY}, ${leftX + arcRadius} ${bottomY}`].join(' ');
    if (bottomRightCurve) {
      const arcWidth = 30;
      const arcHeight = 30;
      d += ` L ${rightX - arcWidth} ${bottomY} C ${rightX - arcWidth / 2} ${bottomY}, ${rightX} ${bottomY - arcHeight / 2}, ${rightX} ${bottomY - arcHeight}`;
    } else {
      d += ` L ${rightX} ${bottomY}`;
    }
    d += ` L ${rightX} ${topY} L ${leftX + arcRadius} ${topY}`;
  }
  console.log(d);
  return new hand_drawn_shape({
    stroke,
    strokeWidth,
    fill,
    path: d,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
}
;// ./src/packages/smart-graphics/src/graphics/curev-list/components/rect.js



/**
 * 创建一个矩形边框形状（渲染高度严格等于 height）
 * @param {Object} opts
 * @param {number} opts.width - 总宽度
 * @param {number} opts.height - 总高度
 * @param {string} opts.fill - 填充色
 * @param {string} opts.stroke - 描边色
 * @param {number} opts.strokeWidth - 描边宽度
 * @param {number} [opts.cornerRadius=0] - 可选，圆角半径
 * @returns {Group}
 */
function createRectShape({
  width = 602,
  height = 86,
  fill = 'none',
  stroke = '#DE58A9',
  strokeWidth = 2,
  cornerRadius = 2,
  handDrawn,
  handDrawnStyle
} = {}) {
  const halfStroke = strokeWidth / 2;

  // 边界直接使用 height 和 width，不做额外偏移
  const leftX = 0 + halfStroke;
  const topY = 0 + halfStroke;
  const rightX = width - halfStroke;
  const bottomY = height - halfStroke;
  let d;
  if (cornerRadius > 0) {
    const r = Math.min(cornerRadius, width / 2, height / 2);
    d = [`M ${leftX + r} ${topY}`, `H ${rightX - r}`, `A ${r} ${r} 0 0 1 ${rightX} ${topY + r}`, `V ${bottomY - r}`, `A ${r} ${r} 0 0 1 ${rightX - r} ${bottomY}`, `H ${leftX + r}`, `A ${r} ${r} 0 0 1 ${leftX} ${bottomY - r}`, `V ${topY + r}`, `A ${r} ${r} 0 0 1 ${leftX + r} ${topY}`, 'Z'].join(' ');
  } else {
    d = [`M ${leftX} ${topY}`, `H ${rightX}`, `V ${bottomY}`, `H ${leftX}`, 'Z'].join(' ');
  }
  return new hand_drawn_shape({
    stroke,
    strokeWidth,
    fill,
    path: d,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
}
