/**
 * 根据总高度生成柱状图（曲率固定，竖线高度可变）
 * @param {Object} opts
 * @param {number} opts.height - 总高度（竖线到顶部的高度）
 * @param {string} opts.stroke - 描边颜色
 * @param {string} opts.fill - 填充颜色
 */
function createColumnShape(opts) {
  const {
    height = 150,
    stroke = '#000',
    fill = '#fff',
    needTop = true,
    handDrawn,
    handDrawnStyle
  } = opts;

  // 顶部固定曲线参数
  const topLeftStart = {
    x: 35.347656,
    y: 29.4164
  };
  const topLeftEnd = {
    x: 39.589656,
    y: 16
  };
  const topLeftCtrl1 = {
    x: 35.347656,
    y: 24.4588
  };
  const topLeftCtrl2 = {
    x: 37.036556,
    y: 19.7576
  };
  const topRightStart = {
    x: 135.489656,
    y: 16
  };
  const topRightEnd = {
    x: 131.347656,
    y: 29.4164
  };
  const topRightCtrl1 = {
    x: 133.036556,
    y: 19.7576
  };
  const topRightCtrl2 = {
    x: 131.347656,
    y: 24.4587
  };

  // 底部曲线原始参数（相对于竖线底部）
  const bottomLeftStart = {
    x: 35.3474,
    y: 88.871094
  };
  const bottomLeftEnd = {
    x: 16,
    y: 111.951194
  };
  const bottomLeftCtrl1 = {
    x: 35.3474,
    y: 96.341794
  };
  const bottomLeftCtrl2 = {
    x: 30.7018,
    y: 103.170994
  };
  const bottomLeftCtrl3 = {
    x: 23.3474,
    y: 106.511994
  };
  const bottomLeftCtrl4 = {
    x: 20.4326,
    y: 107.836194
  };
  const bottomLeftCtrl5 = {
    x: 17.9432,
    y: 109.708294
  };
  const bottomRightStart = {
    x: 131.3474,
    y: 88.871094
  };
  const bottomRightEnd = {
    x: 112.9568,
    y: 112.001194
  };
  const bottomRightCtrl1 = {
    x: 131.3474,
    y: 96.341794
  };
  const bottomRightCtrl2 = {
    x: 126.7018,
    y: 103.170994
  };
  const bottomRightCtrl3 = {
    x: 119.3474,
    y: 106.511994
  };
  const bottomRightCtrl4 = {
    x: 116.4109,
    y: 107.845994
  };
  const bottomRightCtrl5 = {
    x: 113.9063,
    y: 109.736094
  };

  // 竖线高度由总高度决定
  const verticalTop = topLeftEnd.y; // 16
  const verticalBottom = height - 7;

  // 上竖线
  const leftVerticalEnd = {
    x: topLeftStart.x,
    y: verticalBottom
  };
  const rightVerticalEnd = {
    x: topRightEnd.x,
    y: verticalBottom
  };

  // 底部曲线随竖线平移
  const bottomOffset = verticalBottom - bottomLeftStart.y;

  // 生成路径
  const pathData = `
M ${topLeftStart.x} ${topLeftStart.y} C ${topLeftCtrl1.x} ${topLeftCtrl1.y} ${topLeftCtrl2.x} ${topLeftCtrl2.y} ${topLeftEnd.x} ${topLeftEnd.y}
M ${topRightStart.x} ${topRightStart.y} C ${topRightCtrl1.x} ${topRightCtrl1.y} ${topRightCtrl2.x} ${topRightCtrl2.y} ${topRightEnd.x} ${topRightEnd.y}

M ${topRightEnd.x} ${topRightEnd.y} L ${rightVerticalEnd.x} ${rightVerticalEnd.y}
M ${leftVerticalEnd.x} ${leftVerticalEnd.y} L ${topLeftStart.x} ${topLeftStart.y}

M ${bottomRightStart.x} ${bottomRightStart.y + bottomOffset} 
C ${bottomRightCtrl1.x} ${bottomRightCtrl1.y + bottomOffset} 
  ${bottomRightCtrl2.x} ${bottomRightCtrl2.y + bottomOffset} 
  ${bottomRightCtrl3.x} ${bottomRightCtrl3.y + bottomOffset}
C ${bottomRightCtrl4.x} ${bottomRightCtrl4.y + bottomOffset} 
  ${bottomRightCtrl5.x} ${bottomRightCtrl5.y + bottomOffset} 
  ${bottomRightEnd.x} ${bottomRightEnd.y + bottomOffset}

M ${bottomLeftStart.x} ${bottomLeftStart.y + bottomOffset}
C ${bottomLeftCtrl1.x} ${bottomLeftCtrl1.y + bottomOffset}
  ${bottomLeftCtrl2.x} ${bottomLeftCtrl2.y + bottomOffset}
  ${bottomLeftCtrl3.x} ${bottomLeftCtrl3.y + bottomOffset}
C ${bottomLeftCtrl4.x} ${bottomLeftCtrl4.y + bottomOffset}
  ${bottomLeftCtrl5.x} ${bottomLeftCtrl5.y + bottomOffset}
  ${bottomLeftEnd.x} ${bottomLeftEnd.y + bottomOffset}
`;
  let topPath = `
    M ${topLeftEnd.x} ${topLeftEnd.y + 0.5}
    L ${topRightStart.x - 1} ${topRightStart.y + 0.5}
`;
  const path = new hand_drawn_shape({
    path: pathData,
    strokeWidth: 2,
    stroke,
    strokeCap: 'round',
    strokeJoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
  let path2 = new hand_drawn_shape({
    path: topPath,
    strokeWidth: 2,
    stroke: fill,
    strokeCap: 'round',
    strokeJoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
  const g = new draw_esm_min_Be();
  if (needTop) {
    g.add(path2);
  }
  g.add(path);
  g.y = -verticalTop + 0.5;
  return g;
}
