/**
 * 根据“整体高度”生成图形
 * @param {Object} opts
 * @param {number} opts.height - 整体高度（从顶部最上点16到底部曲线最下点）
 * @param {string} opts.stroke - 描边颜色
 * @param {string} opts.fill - 填充颜色
 */
function createLastColumnShape(opts) {
  const {
    height = 150,
    stroke = '#000',
    fill = '#fff',
    handDrawn,
    handDrawnStyle
  } = opts;

  // 顶部固定
  const TOP_Y = 14; // 顶部最高点
  const TOP_CURVE_Y = 29.4164; // 顶部曲线最低点

  // 原始底部曲线参数（你的大高度版本）
  const ORI_BOTTOM_START = 101.750008; // 曲线起点
  const ORI_BOTTOM_END = 147.999208; // 曲线最底端
  const ORI_BOTTOM_H = ORI_BOTTOM_END - ORI_BOTTOM_START;

  // ★ 目标底部曲线最底端（满足整体高度 = height）
  const NEW_BOTTOM_END = TOP_Y + height;

  // ★ 新底部曲线起点 = 新底端 - 原始曲线高度
  const NEW_BOTTOM_START = NEW_BOTTOM_END - ORI_BOTTOM_H;

  // ★ 竖线底部必须与底部曲线起点对齐
  const VERTICAL_BOTTOM = NEW_BOTTOM_START;

  // 生成路径（顶部完全不变）
  const pathStr = `
M 16 ${TOP_CURVE_Y}C 16 24.4588 17.6889 19.7576 19.5 ${TOP_Y}
M 115.8 ${TOP_Y}C 113.6889 19.7576 112 24.4587 112 ${TOP_CURVE_Y}

M 112 ${TOP_CURVE_Y}L 112 ${VERTICAL_BOTTOM}
M 16 ${VERTICAL_BOTTOM}L 16 ${TOP_CURVE_Y}

M 16 ${NEW_BOTTOM_START}
C 16 ${NEW_BOTTOM_START + 25.5427}
  36.7065 ${NEW_BOTTOM_END}
  62.2492 ${NEW_BOTTOM_END}
L 65.7508 ${NEW_BOTTOM_END}
C 91.2935 ${NEW_BOTTOM_END}
  112 ${NEW_BOTTOM_START + 25.5427}
  112 ${NEW_BOTTOM_START}
`;
  let path2 = new hand_drawn_shape({
    path: `
        M 20 ${TOP_Y + 0.5}
        L 115 ${TOP_Y + 0.5}
    `,
    stroke: fill,
    strokeWidth: 2,
    // strokeCap: 'round',
    strokeJoin: 'round',
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });
  const path = new hand_drawn_shape({
    path: pathStr,
    stroke,
    strokeCap: 'round',
    strokeWidth: 2,
    shapeClass: draw_esm_min_hi,
    handDrawn: handDrawn,
    handDrawnStyle: handDrawnStyle
  });

  // TopY = 16 顶部固定，但图形要从 0 开始显示 ⇒ 整体上移
  const g = new draw_esm_min_ge();
  g.y = -TOP_Y + 0.5;
  g.add(path2);
  g.add(path);
  g.fill = fill;
  return g;
}
