class CurveRightItemNode extends node_Node_Node {
  minWidth = 310;
  maxWidth = 1600;
  config = {
    width: 528,
    tagStepIncrease: 24,
    itemHeight: 96,
    flgWidth: 76,
    flowGap: 45
  };
  constructor(options = {}) {
    super(options);
    this.nodeStyle = this.style.getStyle();
  }
  setData() {
    super.setData(...arguments);
    this.nodeStyle = this.style?.getStyle();
  }
  getTitleFontStyle() {
    let defaultStyle = {
      fontSize: 20,
      fontWeight: 400,
      lineHeight: '24px',
      color: '#000000'
    };
    return {
      ...defaultStyle,
      ...this.nodeStyle.title
    };
  }
  getIcon(SvgIcon, color) {
    let nodeStyle = this.nodeStyle;
    return new Avatar({
      id: 'node-icon-' + this.id,
      src: SvgIcon || this._data.icon,
      ...nodeStyle.icon,
      onClick: () => {
        this._ctx.emit(src_constant_EVENT_TYPE.NODE_ICON_CLICK, this.id);
      },
      color: color || (0,tools/* mergeAlternateArray */.E$)(nodeStyle.icon.color.stroke, nodeStyle.icon.color.fill),
      radius: 0,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: this.id
      }
    }).getElement();
  }
  getDescFontStyle() {
    let defaultStyle = {
      fontSize: 15,
      lineHeight: '18px',
      fontWeight: 400,
      color: '#000000'
    };
    return {
      ...defaultStyle,
      ...this.nodeStyle.description
    };
  }
  getFlagStyle() {
    return {
      fontSize: 25,
      fontWeight: 400,
      fill: this.nodeStyle.title.color
    };
  }
  getLayout() {
    const {
      flowGap
    } = this.config;
    return new flow_esm_min_m({
      flow: 'x',
      gap: {
        x: flowGap,
        y: 0
      },
      flowAlign: 'center'
    });
  }
  getItemLayout() {
    return new flow_esm_min_m({
      flow: 'y',
      gap: {
        x: 0,
        y: 8
      }
    });
  }
  _calcTextWidth(width) {
    const {
      flowGap,
      flgWidth,
      tagStepIncrease
    } = this.config;
    const iconWidth = this.nodeStyle?.icon?.iconSize?.width || 0;
    return width + tagStepIncrease * this.index - flgWidth - iconWidth - flowGap * 2;
  }
  _getBgStyle() {
    const {
      graph: graphStyle
    } = this.style.getStyle();
    return {
      fill: graphStyle.color[0].fill[0],
      stroke: graphStyle.color[0].stroke[0],
      ...graphStyle
    };
  }
  _getBgShape(width) {
    const {
      tagStepIncrease,
      itemHeight
    } = this.config;
    const bgColors = this._getBgStyle();
    const isEnd = this.totalLength - 1 === this.index;
    return createComplexTagShape({
      ...bgColors,
      width: width + tagStepIncrease * this.index,
      height: itemHeight,
      bottomRightCurve: isEnd ? true : false,
      needBottom: true
    });
  }
  render() {
    this.group.data = {
      ...this.group.data,
      includeGraph: true
    };
    const bgGroup = new draw_esm_min_ge();
    const {
      size = {}
    } = this.style.getStyle();
    const {
      width: defaultWidth,
      tagStepIncrease,
      flgWidth
    } = this.config;
    const width = size?.width ?? defaultWidth;
    const textWidth = this._calcTextWidth(width);
    const bgColors = this._getBgStyle();
    let isEnd = this.totalLength - 1 === this.index;
    const bg = this._getBgShape(width);
    let fn = createColumnShape;
    if (isEnd) {
      fn = createLastColumnShape;
    }
    let bg2 = fn({
      ...bgColors,
      height: 94,
      needTop: this.index === 0 ? false : true
    });
    bg2.x = 62 + this.index * 1.2;
    if (isEnd) {
      bg2.x = bg2.x + 20;
    }
    bgGroup.add(bg);
    bgGroup.add(bg2);
    let iconFlow = new flow_esm_min_m({
      width: flgWidth,
      height: 94,
      flow: 'y',
      flowAlign: 'right',
      padding: [0, 10, 0, 0]
    });
    // console.log(bg.width, 'leftHeight');
    const flag = new draw_esm_min_i({
      text: this.index + 1 + '',
      ...this.getFlagStyle()
    });
    iconFlow.add(flag);
    const right = this.getItemLayout();
    const title = new RichText({
      id: 'node-title-' + this.id,
      text: this._data.title,
      style: {
        ...this.getTitleFontStyle(this.titleColor),
        width: textWidth,
        maxWidth: textWidth
      },
      onChange: text => {
        this.updateNodeData({
          title: text
        });
      },
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      }
    });
    const desc = new RichText({
      id: 'node-description-' + this.id,
      text: this._data.description,
      style: {
        ...this.getDescFontStyle(),
        width: textWidth,
        maxWidth: textWidth
      },
      onChange: text => {
        this.updateNodeData({
          description: text
        });
      },
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            description: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      }
    });
    this._bgGroup = bgGroup;
    this._bg = bg;
    this._title = title;
    this._desc = desc;
    right.add(title.getElement());
    right.add(desc.getElement());
    const icon = this.getIcon();
    const container = this.getLayout();
    container.add(iconFlow);
    container.add(icon);
    container.add(right);
    // container.add(rightGroup);
    this.group.add(bgGroup);
    this.group.add(container);
    if (!this.isReadonly()) {
      this.setOnlyResizeWidth();
      this.group.widthRange = {
        min: this.minWidth + this.index * tagStepIncrease,
        max: this.maxWidth + this.index * tagStepIncrease
      };
    }
  }
  updateGeometry(width) {
    if (this._bgGroup && this._bg) {
      const bg = this._getBgShape(width);
      this._bgGroup.addBefore(bg, this._bg);
      this._bg.remove();
      this._bg = bg;
    }
    if (this._title) {
      const titleWidth = this._calcTextWidth(width);
      this._title.options.style.width = titleWidth;
      this._title.options.style.maxWidth = titleWidth;
      this._title.render();
    }
    if (this._desc) {
      const descWidth = this._calcTextWidth(width);
      this._desc.options.style.width = descWidth;
      this._desc.options.style.maxWidth = descWidth;
      this._desc.render();
    }
  }
  onScale() {
    const newWidth = this.group.width;
    const tagStepIncrease = this.config.tagStepIncrease || 0;
    this.config.baseWidth = newWidth - this.index * tagStepIncrease;
    this.updateGeometry(this.config.baseWidth);
  }
  onScaleEnd() {
    const newSizeList = this?._ctx?.layoutInstance.getScaleEndItemSize({
      width: this.config.baseWidth
    }, {
      index: this.index
    }) || [];
    const updateMsg = newSizeList.map(({
      id,
      size
    }) => ({
      id,
      data: {
        override: {
          size
        }
      }
    }));
    if (updateMsg.length && this?._ctx?.updateNodesData) {
      this._ctx.updateNodesData(updateMsg);
    }
  }
}
