class RightListGraphics extends SmartGraphics {
  constructor(options = {}, defaultOptions = {}) {
    let defaultOptionsTemp = {
      defaultOptions: {
        nodeMaxNumber: 6,
        nodeMinNumber: 2
      },
      defaultData: {
        nodeStyle: {
          size: {
            width: 400
          },
          icon: {
            iconSize: {
              width: 48,
              height: 48
            }
          }
        }
      }
    };
    super((0,tools/* deepAssign */.Eg)({}, options, defaultOptionsTemp, defaultOptions));
  }
  setFullData(data) {
    super.setFullData(data);
    this.setNodeMap();
  }
  getNodeMap() {
    return {
      RightItemNode: RightItemNode
    };
  }
  getListType() {
    return 'RightItemNode';
  }
  getImageType() {
    return IMAGE_KEYS.KEY;
  }
  getLayout() {
    return new flow_esm_min_m({
      flow: 'x',
      gap: {
        x: 36,
        y: 24
      },
      flowAlign: 'center'
    });
  }
  getListLayout() {
    return new GridLayout({
      ctx: this,
      data: {
        gap: {
          x: 0,
          y: 12
        },
        flow: 'y',
        isAutoHeight: true,
        flowWrap: false
      }
    });
  }
  getDefaultStyle() {
    return {
      title: {
        fontSize: 25,
        fontWeight: 700,
        color: '#000000',
        overflow: 'auto'
      }
    };
  }
  getTitleStyle() {
    let titleStyle = this.data.title?.style || {};
    return {
      ...this.getDefaultStyle().title,
      ...titleStyle
    };
  }
  getTitleElement() {
    const id = 'global-title';
    const title = new RichText({
      id,
      text: this.data.title.text,
      style: this.getTitleStyle(),
      onChange: text => {
        this.updateTitle(text);
      },
      onStyleChange: modifyStyle => {
        this.updateTitleStyle(modifyStyle);
      },
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: id
      }
    });
    return title.getElement();
  }
  getTotalContainer() {
    return new flow_esm_min_m({
      flow: 'y',
      flowAlign: 'center',
      gap: {
        x: 0,
        y: 48
      },
      padding: [24, 48]
    });
  }
  getImageNode() {
    let graphStyle = null;
    const colorCards = this.getNodeList().map(element => {
      if (!graphStyle) graphStyle = element.nodeStyle.graph;
      let colorObj = element.nodeStyle.graph.color[0];
      return {
        fill: colorObj.fill[0],
        stroke: colorObj.stroke[0]
      };
    });
    this.imageNode = getImageNode({
      count: this.data.nodeList.length,
      type: this.imageType,
      colorCards: colorCards,
      graphStyle
    });
    return this.imageNode;
  }
  render() {
    let totalContainer = this.getTotalContainer();
    this.NodeMap = this.getNodeMap();
    this.useNodeType = this.getListType();
    this.imageType = this.getImageType();
    super.render();
    this.layoutInstance = this.getListLayout();
    const container = this.getLayout();
    let image = this.getImageNode();
    // 执行布局渲染：将节点按布局规则组织到渲染容器中
    let listGroup = this.layoutInstance.getList();
    container.add(image);
    container.add(listGroup);
    totalContainer.add(this.getTitleElement());
    totalContainer.add(container);
    this.renderContainer.add(totalContainer);
  }
}
