class CommonRingGraphics extends SmartGraphics {
  NodeMap = {
    TextDescriptionNode: TextDescriptionNode
  };
  useNodeType = 'TextDescriptionNode';
  config = {
    outerRadius: 160,
    innerRadius: 80,
    gapDeg: 0,
    iconPosition: 'center',
    strokeWidth: 2
  };
  constructor(options = {}) {
    const defaultData = {
      nodeStyle: {
        title: {
          fontSize: 20,
          maxWidth: 260,
          textAlign: 'center'
        },
        description: {
          fontSize: 15,
          maxWidth: 260,
          textAlign: 'center'
          // verticalAlign: 'middle', // 高度大于内容高度时内容居中显示
          // height: 100, // 富文本高度
        },
        icon: {
          iconSize: {
            width: 36,
            height: 36
          }
        }
      }
    };
    super({
      ...options,
      defaultData: (0,tools/* deepAssign */.Eg)({}, defaultData, options.defaultData)
    });
  }
  render() {
    super.render();
    // const { width, height } = this.opts;
    const data = this.data;
    let graphicsTitle;
    if (data.title?.show) {
      graphicsTitle = new RichText({
        ...data.title,
        onChange: text => {
          this.updateTitle(text);
        },
        onStyleChange: modifyStyle => {
          this.updateTitle(undefined, modifyStyle);
        },
        id: `graph-title`,
        editable: true,
        customData: {
          entityType: ENTITY_TYPE.RICH_TEXT
        }
      });
    }
    const nodeList = this.getNodeList();
    nodeList.forEach(node => {
      node.render();
    });
    const centerConfig = {
      ...(this.config.centerConfig || {})
    };
    let outerRadius = this.config.outerRadius;
    let innerRadius = this.config.innerRadius;
    // if (width && height) {
    //   const scale = width / outerRadius;
    //   outerRadius *= scale;
    //   innerRadius *= scale;
    //   if (centerConfig?.show) {
    //     centerConfig.radius *= scale;
    //   }
    // }
    if (centerConfig?.show) {
      if (data.icon) {
        // const avatar = new Avatar({
        //   ...(data.icon.style || {}),
        //   src: data.icon.src,
        // });
        // centerConfig.element = avatar.getElement();

        const graphStyle = nodeList[0].style.getStyle().graph;
        centerConfig.fill = graphStyle.color[1].fill[0];
        centerConfig.handDrawnStyle = {
          handDrawn: graphStyle.handDrawn,
          handDrawnStyle: graphStyle.handDrawnStyle
        };
      }
    }
    const splitCircle = new SplitCircle({
      ...this.config,
      outerRadius,
      innerRadius,
      fillColors: this._getFillColor(),
      dataList: this._getDataList(),
      strokeColors: this._getStrokeColor(),
      handDrawStyleList: this._getHandDrawnStyleList(),
      centerConfig,
      editable: true
    });
    if (splitCircle.textPositionMap.size > 0) {
      nodeList.forEach((node, index) => {
        let side = splitCircle.textPositionMap.get(index);
        if (this.config.iconPosition === 'center' && nodeList.length % 2 !== 0 && index + 1 === Math.ceil(nodeList.length / 2)) {
          side = 'center';
        }
        if (this.config.iconPosition === 'start' && (index === 0 || (nodeList.length - 1) % 2 !== 0 && index % Math.ceil(nodeList.length / 2) === 0)) {
          side = 'center';
        }
        if (side !== 'center') {
          node.render({
            textAlign: side === 'right' ? 'left' : 'right'
          });
        }
      });
    }
    if (graphicsTitle) {
      const flow = new flow_esm_min_m({
        flow: 'y',
        flowAlign: 'center',
        gap: 50,
        children: [graphicsTitle.getElement(), splitCircle.getElement()]
      });
      this.renderContainer.add(flow);
    } else {
      this.renderContainer.add(splitCircle.getElement());
    }
  }
  _getHandDrawnStyleList() {
    const nodeList = this.getNodeList();
    return nodeList.map(node => {
      const graphStyle = node.style.getStyle().graph;
      return {
        handDrawn: graphStyle.handDrawn,
        handDrawnStyle: graphStyle.handDrawnStyle
      };
    });
  }
  _getDataList() {
    const nodeList = this.getNodeList();
    const dataList = nodeList.map(node => {
      return {
        text: node.group,
        icon: this.renderIcon(node),
        customData: {
          entityType: ENTITY_TYPE.NODE_GRAPH,
          nodeId: node.id
        },
        id: `node-graph-${node.id}`
      };
    });
    return dataList;
  }
  _getFillColor() {
    const nodeList = this.getNodeList();
    return nodeList.map(node => node.style.getStyle().graph.color[0].fill[0]);
  }
  _getStrokeColor() {
    const nodeList = this.getNodeList();
    return nodeList.map(node => node.style.getStyle().graph.color[0].stroke[0]);
  }
  renderIcon(node) {
    const style = node.style.getStyle().icon || {};
    const src = node.data.icon || icon_IconList[node.index % icon_IconList.length];
    const avatar = new Avatar({
      src,
      ...style,
      color: (0,tools/* mergeAlternateArray */.E$)(style.color.stroke, style.color.fill),
      onClick: () => {
        this.emit(src_constant_EVENT_TYPE.NODE_ICON_CLICK, node.id, src);
      },
      id: `node-icon-${node.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: node.id
      }
    });
    return avatar.getElement();
  }
}
