class DotIconRing extends CommonRingGraphics {
  config = {
    outerRadius: 160,
    innerRadius: 150,
    gapDeg: 0,
    iconPosition: 'start',
    strokeWidth: 2
  };
  constructor(options = {}) {
    super({
      ...options,
      defaultData: {
        nodeStyle: {
          title: {
            maxWidth: 160,
            lineClamp: 2,
            textAlign: 'center'
          },
          description: {
            maxWidth: 160,
            lineClamp: 3,
            textAlign: 'center'
          }
        }
      }
    });
  }
  renderIcon(node) {
    const style = node.style.getStyle().icon || {};
    const pen = new draw_esm_min_di();
    pen.setStyle({
      fill: '#ffffff',
      stroke: style.color.stroke[0],
      strokeWidth: 3
    });
    pen.arc(15, 15, 15);
    pen.setStyle({
      fill: style.color.stroke[0]
    });
    pen.arc(15, 15, 7);
    return pen;
  }
}
