;// ./src/packages/smart-graphics/src/graphics/walk-ladder/nodes/icon-text.js






class icon_text_IconText extends node_Node_Node {
  minWidth = 180;
  maxWidth = 1600;
  size = {
    flowGap: 36
  };
  constructor() {
    super(...arguments);
  }
  render() {
    const nodeStyle = this.style.getStyle();
    const titleWidth = this._calcTitleWidth(nodeStyle.size?.width) || 300;
    const textStepIncrease = this._ctx.textStepIncrease || 0;
    const {
      flowGap
    } = this.size;
    const flow = new flow_esm_min_m({
      padding: nodeStyle.padding,
      flow: 'x',
      flowAlign: 'center',
      gap: {
        x: flowGap,
        y: 0
      }
    });
    const icon = new Avatar({
      id: 'node-icon-' + this.id,
      src: this.data.icon,
      ...nodeStyle.icon,
      color: (0,tools/* mergeAlternateArray */.E$)(nodeStyle.icon.color.stroke, nodeStyle.icon.color.fill),
      radius: 0,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: this.id
      }
    });
    const title = new RichText({
      id: 'node-title-' + this.id,
      text: this.data.title,
      style: {
        ...nodeStyle.title,
        height: nodeStyle?.size?.height,
        width: titleWidth + this.index * textStepIncrease,
        maxWidth: titleWidth + this.index * textStepIncrease
      },
      onChange: text => {
        this.updateNodeData({
          title: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      }
    });
    flow.add(icon.getElement());
    flow.add(title.getElement());
    this.group.add(flow);
    this._wrapper = flow;
    this._title = title;
    if (!this.isReadonly()) {
      this.setOnlyResizeWidth();
      this.group.widthRange = {
        min: this.minWidth + this.index * textStepIncrease,
        max: this.maxWidth + this.index * textStepIncrease
      };
    }
  }
  _calcTitleWidth(width) {
    const nodeStyle = this.style.getStyle();
    return width - this.size.flowGap - nodeStyle.icon.iconSize?.width;
  }
  updateGeometry(width) {
    const titleWidth = this._calcTitleWidth(width);
    // 更新标题和描述的最大宽度并重新渲染
    this._title.options.style.width = titleWidth;
    this._title.options.style.maxWidth = titleWidth;
    this._title.render();
  }
  onScale() {
    const newWidth = this.group.width;
    const textStepIncrease = this._ctx.textStepIncrease || 0;
    this.size.baseWidth = newWidth - this.index * textStepIncrease;
    this.updateGeometry(newWidth);
  }
  onScaleEnd() {
    const newSizeList = this?._ctx?.layoutInstance.getScaleEndItemSize({
      width: this.size.baseWidth
    }, {
      index: this.index
    }) || [];
    const updateMsg = newSizeList.map(({
      id,
      size
    }) => ({
      id,
      data: {
        override: {
          size
        }
      }
    }));
    if (updateMsg.length && this?._ctx?.updateNodesData) {
      this._ctx.updateNodesData(updateMsg);
    }
  }
}
