/**
 * 根据总高度和阶高生成连续上升的台阶数据（返回独立对象数组）
 * @param {object} props - 台阶属性对象
 * @param {number} props.startX - 起始X坐标
 * @param {number} props.startY - 起始Y坐标
 * @param {number} props.stepHeight - 单个台阶的垂直高度
 * @param {number} props.stepWidth - 所有台阶的标准宽度
 * @param {number} props.topWidth - 最顶端台阶的特殊宽度
 * @param {number} props.totalHeight - 从起点到顶部平台顶端的总垂直高度
 * @returns {Array<object>} 包含每个台阶数据的对象数组
 */
function generateStepDataFromHeight(props) {
  const {
    startX,
    startY,
    stepHeight,
    stepWidth,
    topWidth,
    totalHeight
  } = props;
  const numSteps = Math.floor(totalHeight / stepHeight);
  const steps = [];
  const xIncrement = stepWidth;
  const yIncrement = -stepHeight;
  for (let i = 0; i < numSteps; i++) {
    const isLastStep = i === numSteps - 1;
    const currentWidth = isLastStep ? topWidth : stepWidth;
    const x = startX + i * xIncrement;
    const y = startY + i * yIncrement;
    const points = [x, y, x, y - stepHeight, x + currentWidth, y - stepHeight];
    steps.push({
      points,
      index: i + 1,
      width: currentWidth,
      isLast: isLastStep
    });
  }
  return steps;
}
