class TextNode extends node_Node_Node {
  minWidth = 100;
  maxWidth = 1600;
  size = {
    flowGap: 36,
    lineWidth: 168
  };
  constructor() {
    super(...arguments);
  }
  render() {
    const nodeStyle = this.style.getStyle();
    const titleWidth = nodeStyle.size.width;
    const title = new RichText({
      id: 'node-title-' + this.id,
      text: this._data.title,
      style: {
        ...nodeStyle.title,
        width: titleWidth
      },
      onChange: text => {
        this.updateNodeData({
          title: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      }
    });
    this.group.add(title.getElement());
    this._title = title;
    if (!this.isReadonly()) {
      this.setOnlyResizeWidth();
      this.group.data = {
        ...this.group.data,
        includeRichTextId: `node-title-${this.id}`
      };
      this.group.widthRange = {
        min: this.minWidth,
        max: this.maxWidth
      };
    }
  }
  updateGeometry(width) {
    // 更新标题和描述的最大宽度并重新渲染
    this._title.options.style.width = width;
    this._title.options.style.maxWidth = width;
    this._title.render();
  }
  onScale() {
    const newWidth = this.group.width;
    this.updateGeometry(newWidth);
  }
  onScaleEnd() {
    const newSizeList = this?._ctx?.layoutInstance.getScaleEndItemSize({
      width: this.group.width
    }, {
      index: this.index
    }) || [];
    const updateMsg = newSizeList.map(({
      id,
      size
    }) => ({
      id,
      data: {
        override: {
          size
        }
      }
    }));
    if (updateMsg.length && this?._ctx?.updateNodesData) {
      this._ctx.updateNodesData(updateMsg);
    }
  }
}
