/**
 * 生成边缘平滑的梯形金字塔函数
 * @param {object} baseProps - 基础属性对象
 * @param {number} baseProps.x - 金字塔顶点的X坐标
 * @param {number} baseProps.y - 金字塔顶点的Y坐标
 * @param {number} baseProps.topWidth - 顶层（第一层）的宽度
 * @param {number} baseProps.height - 金字塔的总高度
 * @param {number} baseProps.layers - 金字塔的总层数
 * @returns {Array<object>} 包含每一层梯形顶点数据的对象数组
 */
function generateSmoothPyramid(baseProps) {
  const {
    x: peakX,
    y: peakY,
    topWidth: topWidth,
    height: totalHeight,
    bottomWidth: bottomWidth,
    layers
  } = baseProps;
  const pyramidLayers = [];
  const layerHeight = totalHeight / layers;

  // 从顶层 (i=1) 到底层 (i=layers) 循环
  for (let i = 1; i <= layers; i++) {
    // 计算当前层上下两边的Y坐标
    const yTop = peakY + (i - 1) * layerHeight;
    const yBottom = peakY + i * layerHeight;

    // --- 核心逻辑：使用线性插值计算宽度 ---
    // 计算当前高度占总高度的比例
    const ratioTop = (yTop - peakY) / totalHeight;
    const ratioBottom = (yBottom - peakY) / totalHeight;

    // 根据比例计算上下边的宽度
    const widthTop = topWidth + ratioTop * (bottomWidth - topWidth);
    const widthBottom = topWidth + ratioBottom * (bottomWidth - topWidth);

    // 根据中心点和宽度计算梯形的四个顶点
    const xTopLeft = peakX - widthTop / 2;
    const xTopRight = peakX + widthTop / 2;
    const xBottomLeft = peakX - widthBottom / 2;
    const xBottomRight = peakX + widthBottom / 2;

    // 按顺序定义梯形的四个顶点
    const points = [xTopLeft, yTop, xTopRight, yTop, xBottomRight, yBottom, xBottomLeft, yBottom];
    pyramidLayers.push({
      points: points,
      level: i
    });
  }
  return pyramidLayers;
}
