class TextDescriptionAvatarNode extends node_Node_Node {
  side = 'left';
  render() {
    this.group.clear();
    const nodeStyle = this.style.getStyle();
    const wrapFlow = new flow_esm_min_m({
      flow: this.side === 'left' ? 'x' : 'x-reverse',
      gap: 8
    });
    const flow = new flow_esm_min_m({
      flow: 'y',
      flowAlign: this.side === 'left' ? 'right' : 'left',
      gap: 4,
      padding: 0
    });
    const title = new RichText({
      text: this._data.title,
      style: {
        ...nodeStyle.title,
        textAlign: this.side === 'left' ? 'right' : 'left'
      },
      onChange: text => {
        const newData = {
          title: text
        };
        this.updateNodeData(newData);
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      id: `node-title-${this.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      }
    });
    const des = new RichText({
      text: this._data.description,
      style: {
        ...nodeStyle.description,
        textAlign: this.side === 'left' ? 'right' : 'left'
      },
      onChange: text => {
        this.updateNodeData({
          description: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            description: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      id: `node-des-${this.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id,
        editable: true
      }
    });
    flow.add(title.getElement());
    flow.add(des.getElement());
    wrapFlow.add(flow);
    const iconStyle = this.style.getStyle().icon || {};
    const src = this.data.icon || icon_IconList[this.index % icon_IconList.length];
    const avatar = new Avatar({
      src,
      ...iconStyle,
      color: (0,tools/* mergeAlternateArray */.E$)(iconStyle.color.stroke, iconStyle.color.fill),
      onClick: () => {
        this._ctx.emit(src_constant_EVENT_TYPE.NODE_ICON_CLICK, this.id, src);
      },
      id: `node-icon-${this.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: this.id
      }
    });
    wrapFlow.add(avatar.getElement());
    this.group.add(wrapFlow);
  }
}
