class ArrowStepNode extends node_Node_Node {
  arrowWidth = 35;
  defaultWidth = 180;
  defaultHeight = 100;
  maxWidth = 320;
  constructor(options) {
    super(options);
  }
  render(resizeInfo = {}) {
    const nodeStyle = this.style.getStyle();
    const width = resizeInfo?.width || nodeStyle.size?.width || this.defaultWidth;
    const height = nodeStyle.size?.height || this.defaultHeight;
    const strokeWidth = nodeStyle.graph.strokeWidth || 2;
    const topGroup = new draw_esm_min_ge();
    const polygon = new draw_esm_min_Me({
      stroke: nodeStyle.graph.color[0].stroke[0],
      strokeWidth,
      points: this.index === 0 ? [0, 0, width - this.arrowWidth, 0, width, height / 2, width - this.arrowWidth, height, 0, height] : [0, 0, width - this.arrowWidth, 0, width, height / 2, width - this.arrowWidth, height, 0, height, this.arrowWidth, height / 2],
      fill: nodeStyle.graph.color[0].fill[0]
    });
    const hPolygon = new hand_drawn_shape({
      stroke: nodeStyle.graph.color[0].stroke[0],
      strokeWidth,
      path: polygon.getPathString(true),
      fill: nodeStyle.graph.color[0].fill[0],
      shapeClass: draw_esm_min_hi,
      handDrawn: nodeStyle.graph.handDrawn,
      handDrawnStyle: nodeStyle.graph.handDrawnStyle
    });
    topGroup.add(hPolygon);
    const title = new RichText({
      text: this._data.title,
      style: {
        ...nodeStyle.title,
        width: width - this.arrowWidth * 2 - strokeWidth,
        height: height - strokeWidth
      },
      onChange: text => {
        this.updateNodeData({
          title: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      editable: true,
      id: `node-title-${this.id}`,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      }
    });
    const titleElement = title.getElement();
    titleElement.x = this.arrowWidth + strokeWidth / 2;
    titleElement.y = strokeWidth / 2;
    topGroup.add(titleElement);
    const des = new RichText({
      text: this._data.description,
      style: {
        ...nodeStyle.description,
        width: width - this.arrowWidth
      },
      onChange: text => {
        this.updateNodeData({
          description: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            description: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      editable: true,
      id: `node-description-${this.id}`,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      }
    });
    const wrap = new flow_esm_min_m({
      flow: 'y',
      gap: 30,
      width: width,
      children: [topGroup, des.getElement()]
    });
    this.group.add(wrap);
    if (!this.isReadonly()) {
      this.group.data = {
        ...this.group.data,
        includeGraph: true
      };
      this.setOnlyResizeWidth();
      this.group.widthRange = {
        min: this.defaultWidth,
        max: this.maxWidth
      };
    }
    this._polygon = polygon;
    this._hPolygon = hPolygon;
    this._title = title;
    this._titleElement = titleElement;
    this._des = des;
    this._wrap = wrap;
    return this.group;
  }
  updateGeometry(width, height, nodeStyle) {
    const strokeWidth = nodeStyle.graph.strokeWidth || 2;

    // Update polygon points
    let points;
    if (this.index === 0) {
      points = [0, 0, width - this.arrowWidth, 0, width, height / 2, width - this.arrowWidth, height, 0, height];
    } else {
      points = [0, 0, width - this.arrowWidth, 0, width, height / 2, width - this.arrowWidth, height, 0, height, this.arrowWidth, height / 2];
    }
    this._polygon.points = points;
    this._hPolygon.path = this._polygon.getPathString(true);

    // Update title
    this._title.options.style.width = width - this.arrowWidth * 2 - strokeWidth;
    this._title.options.style.height = height - strokeWidth;
    this._title.render();
    this._titleElement.x = this.arrowWidth + strokeWidth / 2;
    this._titleElement.y = strokeWidth / 2;

    // Update description
    this._des.options.style.width = width - this.arrowWidth;
    this._des.render();

    // Update wrap
    this._wrap.width = width;
  }
  onScale() {
    const newWidth = this.group.width;
    const nodeStyle = this.style.getStyle();
    const height = nodeStyle.size?.height || this.defaultHeight;
    this.updateGeometry(newWidth, height, nodeStyle);
  }
  onScaleEnd() {
    const {
      width
    } = this.group;
    this.updateNodeData({
      override: {
        size: {
          width
        }
      }
    });
  }
  destroy() {
    this._polygon = null;
    this._hPolygon = null;
    this._title = null;
    this._titleElement = null;
    this._des = null;
    this._wrap = null;
    super.destroy();
  }
}
