class UnidirectionalArrowSteps extends SmartGraphics {
  NodeMap = {
    ArrowStepNode: ArrowStepNode
  };
  useNodeType = 'ArrowStepNode';
  backDistance = 20;
  constructor(options) {
    const defaultData = {
      nodeStyle: {
        title: {
          fontSize: 20,
          textAlign: 'center',
          verticalAlign: 'middle',
          maxWidth: undefined
        },
        description: {
          fontSize: 16,
          textAlign: 'center',
          maxWidth: undefined
        }
      }
    };
    super({
      ...options,
      defaultData: (0,tools/* deepAssign */.Eg)({}, defaultData, options.defaultData),
      nodeDragSortType: 'left-right'
    });
  }
  render() {
    super.render();
    const data = this.data;
    let graphicsTitle;
    if (data.title?.show) {
      graphicsTitle = new RichText({
        ...data.title,
        onChange: text => {
          this.updateTitle(text);
        },
        onStyleChange: modifyStyle => {
          this.updateTitle(undefined, modifyStyle);
        },
        id: `graph-title`,
        editable: true,
        customData: {
          entityType: ENTITY_TYPE.RICH_TEXT
        }
      });
    }
    const nodeListGroup = new draw_esm_min_ge();
    const nodeList = this.getNodeList();
    let baseX = this.backDistance;
    nodeList.forEach(node => {
      node.render();
      node.group.x = baseX - this.backDistance;
      baseX += node.getBounds().width;
      nodeListGroup.addAt(node.group, 0);
    });
    if (graphicsTitle) {
      const flow = new flow_esm_min_m({
        flow: 'y',
        flowAlign: 'center',
        gap: 50,
        children: [graphicsTitle.getElement(), nodeListGroup]
      });
      this.renderContainer.add(flow);
    } else {
      this.renderContainer.add(nodeListGroup);
    }
  }
}
