class TrendNode extends node_Node_Node {
  serialSize = {
    width: 50,
    height: 50
  };
  minWidth = 100;
  maxWidth = 400;
  render(style = {}) {
    this.group.clear();
    const nodeStyle = this.style.getStyle();
    const nodeWidth = nodeStyle.size.width;
    const flow = new flow_esm_min_m({
      flow: 'y',
      width: nodeWidth,
      flowAlign: style.textAlign || 'center',
      gap: 4,
      padding: 0
    });
    this._textFlow = flow;
    const title = new RichText({
      text: this._data.title,
      style: {
        ...nodeStyle.title,
        color: '#212930',
        maxWidth: nodeWidth
      },
      onChange: text => {
        const newData = {
          title: text
        };
        this.updateNodeData(newData);
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      id: `node-title-${this.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      }
    });
    this._title = title;
    const des = new RichText({
      text: this._data.description,
      style: {
        ...nodeStyle.description,
        ...style,
        maxWidth: nodeWidth
      },
      onChange: text => {
        this.updateNodeData({
          description: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            description: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      },
      id: `node-des-${this.id}`,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id,
        editable: true
      }
    });
    this._description = des;
    flow.add(title.getElement());
    flow.add(des.getElement());
    const wrapFlow = new flow_esm_min_m({
      flow: 'y',
      width: nodeWidth,
      flowAlign: 'top',
      gap: 20,
      padding: 0
    });
    wrapFlow.add(flow);
    this._wrapFlow = wrapFlow;
    const serial = new draw_esm_min_ge({});
    const serialBg = new hand_drawn_shape({
      width: this.serialSize.width,
      height: this.serialSize.height,
      fill: nodeStyle.graph.color[0].fill[0],
      stroke: nodeStyle.graph.color[0].stroke[0],
      strokeWidth: 2,
      cornerRadius: this.serialSize.width / 2,
      shapeClass: draw_esm_min_we,
      handDrawn: nodeStyle.graph.handDrawn,
      handDrawnStyle: nodeStyle.graph.handDrawnStyle
    });
    serial.add(serialBg);
    const serialText = new RichText({
      text: this.index + 1,
      editableText: false,
      style: {
        ...nodeStyle.serial,
        color: this.style.getSerialVisibleColor('#212930'),
        width: this.serialSize.width,
        height: this.serialSize.height,
        textAlign: 'center',
        verticalAlign: 'middle'
      }
    });
    serial.add(serialText.getElement());
    if (this.index % 2 === 0) {
      wrapFlow.addAt(serial, 0);
    } else {
      wrapFlow.add(serial);
    }
    this.group.add(wrapFlow);
    if (!this.isReadonly()) {
      this.group.data = {
        ...this.group.data,
        includeGraph: true
      };
      this.setOnlyResizeWidth();
      this.group.widthRange = {
        min: this.minWidth,
        max: this.maxWidth
      };
    }
  }
  onScale() {
    const newWidth = this.group.width;
    this.updateGeometry(newWidth);
  }
  onScaleEnd() {
    const {
      width
    } = this.group;
    this.updateNodeData({
      override: {
        size: {
          width
        }
      }
    });
  }
  updateGeometry(width) {
    if (this._textFlow) {
      this._textFlow.width = width;
    }
    if (this._wrapFlow) {
      this._wrapFlow.width = width;
    }
    if (this._title) {
      this._title.setStyle({
        maxWidth: width
      });
    }
    if (this._description) {
      this._description.setStyle({
        maxWidth: width
      });
    }
  }
  destroy() {
    this._title?.destroy();
    this._description?.destroy();
    this._group?.destroy();
  }
}
