    const avatar = new Avatar({
      src: this._data.icon || icon_IconList[this.index % icon_IconList.length],
      ...nodeStyle.icon,
      color: this.style.getIconVisibleColor('#212930', 'graph.color[0].stroke[0]'),
      id: `node-icon-${this.id}`,
      editable: true,
      padding: 12,
      background: iconBackground,
      backgroundRadius: 12,
      customData: {
        entityType: ENTITY_TYPE.NODE_ICON,
        nodeId: this.id
      }
    });
