class SerialBgCardNode extends IconCardNode {
  cardStrokeWidth = 0;
  cardPadding = [8, 16, 8, 0];
  symbolSize = {
    width: 50,
    height: 50
  };
  cardFlowConfig = {
    flow: 'x',
    flowAlign: 'center',
    gap: 28
  };
  getHeadElement() {
    const {
      width,
      height
    } = this.symbolSize;
    const nodeStyle = this.style.getStyle();
    const graphStyle = nodeStyle.graph;
    const fillBg = graphStyle.color[0].fill[0];
    const group = new draw_esm_min_ge();
    const headBg = new hand_drawn_shape({
      width,
      height,
      fill: fillBg,
      strokeWidth: 2,
      stroke: graphStyle.color[0].stroke[0],
      cornerRadius: width / 2,
      shapeClass: draw_esm_min_we,
      handDrawn: graphStyle.handDrawn,
      handDrawnStyle: graphStyle.handDrawnStyle
    });
    group.add(headBg);
    const serial = new RichText({
      text: this.index + 1,
      editableText: false,
      style: {
        ...nodeStyle.serial,
        color: this.style.getSerialVisibleColor('#212930'),
        width: width,
        height: height,
        textAlign: 'center',
        verticalAlign: 'middle'
      }
    });
    group.add(serial.getElement());
    this._headElement = group;
    return {
      element: group,
      size: {
        width
      }
    };
  }
  getNodeFillColor() {
    return 'transparent';
  }
}
