class SerialCardList extends SmartGraphics {
  NodeMap = {
    SerialBgCardNode: SerialBgCardNode
  };
  LayoutMap = {
    GridLayout: GridLayout
  };
  useNodeType = 'SerialBgCardNode';
  useLayoutType = 'GridLayout';
  constructor(options = {}) {
    super({
      ...options,
      defaultOptions: {
        nodeMinNumber: 1,
        nodeMaxNumber: 20
      },
      defaultData: {
        nodeStyle: {
          serial: {
            fontSize: 24
          }
        }
      },
      nodeDragSortType: 'top-bottom'
    });
  }
  render() {
    super.render();
    this.layoutInstance.layoutOptions = {
      minLineCount: 1,
      maxLineCount: 1,
      lineCount: 1,
      stretchLastRowChange: true,
      gap: {
        x: 0,
        y: 16
      }
    };
    this.layoutInstance.render();
    const layoutWidth = this.layoutInstance.group.width;
    const flow = new flow_esm_min_m({
      width: layoutWidth,
      flow: 'y',
      gap: {
        x: 0,
        y: 24
      }
    });
    const titleFlow = new flow_esm_min_m({
      autoWidth: 1,
      flow: 'x',
      flowAlign: 'center'
    });
    const {
      data: {
        title: {
          id = 'graphic-title',
          text,
          style = {}
        } = {}
      } = {}
    } = this;
    const titleText = new RichText({
      text,
      style: {
        ...style
      },
      onChange: text => {
        this.updateTitle(text);
      },
      editable: true,
      id,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT
      },
      onStyleChange: modifyStyle => {
        this.updateTitleStyle(modifyStyle);
      }
    });
    const titleGroup = new draw_esm_min_ge({
      visible: true,
      locked: false,
      draggable: true
    });
    titleGroup.add(titleText.getElement());
    titleFlow.add(titleGroup);
    flow.add(titleFlow);
    const listFlow = new flow_esm_min_m({
      autoWidth: 1
    });
    listFlow.add(this.layoutInstance.group);
    flow.add(listFlow);
    this.renderContainer.add(flow);
    this.renderLines();
  }
  renderLines() {
    const nodeList = this.getNodeList();
    nodeList.forEach((node, index) => {
      const nodeHeadBounds = node._headElement.worldBoxBounds;
      if (index > 0) {
        const prevNodeHeadBounds = nodeList[index - 1]._headElement.worldBoxBounds;
        const worldStart = {
          x: prevNodeHeadBounds.x + prevNodeHeadBounds.width / 2,
          y: prevNodeHeadBounds.y + prevNodeHeadBounds.height
        };
        const worldEnd = {
          x: nodeHeadBounds.x + nodeHeadBounds.width / 2,
          y: nodeHeadBounds.y
        };
        const start = this.renderContainer.getInnerPoint(worldStart);
        const end = this.renderContainer.getInnerPoint(worldEnd);
        const line = new draw_esm_min_Ze({
          points: [start.x, start.y, end.x, end.y],
          stroke: '#6C7D8F',
          strokeWidth: 1,
          dashPattern: [2, 2]
        });
        this.renderContainer.add(line);
      }
    });
  }
}
