class PkNode extends node_Node_Node {
  minWidth = 150;
  maxWidth = 400;
  defaultWidth = 300;
  defaultHeight = 200;
  slant = 50;
  render({
    width: resizeWidth,
    height: resizeHeight
  } = {}) {
    this.group.clear();
    const nodeStyle = this.style.getStyle();
    const {
      width: nodeWidth,
      height: nodeHeight
    } = nodeStyle.size || {};
    const width = resizeWidth || nodeWidth || this.defaultWidth;
    const height = resizeHeight || nodeHeight || this.defaultHeight;
    this.renderHeight = height;
    const type = this.index === 0 ? 'left' : 'right';
    const padding = [16, 26, 16, 26];
    const contentWidth = width - padding[1] - padding[3] - this.slant;
    this._title = new RichText({
      style: {
        ...nodeStyle.title,
        color: this.style.getTitleVisibleColor(),
        textAlign: type,
        width: contentWidth,
        maxWidth: contentWidth
      },
      id: `node-title-${this.id}`,
      text: this._data.title,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      },
      onChange: text => {
        this.updateNodeData({
          title: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            title: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      }
    });
    this._desc = new RichText({
      style: {
        ...nodeStyle.description,
        color: this.style.getDescriptionVisibleColor(),
        textAlign: type,
        width: contentWidth,
        maxWidth: contentWidth
      },
      id: `node-des-${this.id}`,
      text: this._data.description,
      editable: true,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT,
        nodeId: this.id
      },
      onChange: text => {
        this.updateNodeData({
          description: text
        });
      },
      onStyleChange: modifyStyle => {
        const newData = {
          override: {
            description: {
              ...modifyStyle
            }
          }
        };
        this.updateNodeData(newData);
      }
    });
    this._flow = new flow_esm_min_m({
      width: width - this.slant,
      flow: 'y',
      gap: 4,
      padding,
      children: [this._title.getElement(), this._desc.getElement()]
    });
    if (type === 'right') {
      this._flow.x = this.slant;
    }
    this.group.add(this._flow);
    const slant = this.slant || 0; // Horizontal difference
    let points = [];
    let bgHeight = Math.max(height, this._flow.worldBoxBounds.height);
    if (type === 'left') {
      // Left Node
      points = [0, 0, width, 0, width - slant, bgHeight, 0, bgHeight];
    } else {
      // Right Node
      points = [slant, 0, width, 0, width, bgHeight, 0, bgHeight];
    }
    const color = nodeStyle.graph?.color[0]?.fill[0] || '#1673FF';
    const polygon = new draw_esm_min_Me({
      points,
      cornerRadius: 12
    });
    this._bg = new hand_drawn_shape({
      path: polygon.getPathString(true),
      fill: color,
      points: points,
      cornerRadius: 12,
      strokeWidth: 2,
      stroke: nodeStyle.graph.color[0]?.stroke[0],
      shapeClass: draw_esm_min_Me,
      handDrawn: nodeStyle.graph.handDrawn,
      handDrawnStyle: nodeStyle.graph.handDrawnStyle
    });
    this._bg.x = 0;
    this.group.addAt(this._bg, 0);

    // Enable resize constraints
    if (!this.isReadonly?.()) {
      if (this.setOnlyResizeWidth) {
        this.setOnlyResizeWidth();
      }
      this.group.widthRange = {
        min: this.minWidth,
        max: this.maxWidth
      };
    }
  }
  onScale() {
    this.updateGeometry();
  }
  updateGeometry() {
    const {
      width
    } = this.group;
    const type = this.index === 0 ? 'left' : 'right';
    const padding = [16, 26, 16, 26];
    const contentWidth = width - padding[1] - padding[3] - this.slant;
    const slant = this.slant || 0;

    // Update Text
    if (this._title) {
      this._title.setStyle({
        width: contentWidth,
        maxWidth: contentWidth
      });
    }
    if (this._desc) {
      this._desc.setStyle({
        width: contentWidth,
        maxWidth: contentWidth
      });
    }

    // Update Flow
    if (this._flow) {
      this._flow.width = width - slant;
      this._flow.height = undefined;
    }
    const height = Math.max(this.renderHeight, this._flow.worldBoxBounds.height);

    // Update BG
    let points = [];
    if (type === 'left') {
      points = [0, 0, width, 0, width - slant, height, 0, height];
    } else {
      points = [slant, 0, width, 0, width, height, 0, height];
    }
    const polygon = new draw_esm_min_Me({
      points,
      strokeWidth: 0,
      cornerRadius: 12
    });
    if (this._bg) {
      this._bg.set({
        path: polygon.getPathString(true),
        points,
        width,
        height
      });
    }
  }
  onScaleEnd() {
    const {
      width
    } = this.group;
    this.onScaleEnd?.();
    this.updateNodeData({
      override: {
        size: {
          width
        }
      }
    });
  }
  destroy() {
    this._title?.destroy();
    this._desc?.destroy();
    this._title = null;
    this._desc = null;
    this._flow = null;
    this._bg = null;
    super.destroy();
  }
}
;// ./src/packages/smart-graphics/src/graphics/compare/items-pk/index.js






class ItemsPk extends SmartGraphics {
  NodeMap = {
    PkNode: PkNode
  };
  useNodeType = 'PkNode';
  vsRadius = 50;
  constructor(options = {}) {
    const defaultData = {
      nodeStyle: {
        size: {
          width: 300
        },
        title: {
          fontSize: 20,
          fontWeight: 600,
          textAlign: 'left',
          lineHeight: 1.4
        },
        description: {
          fontSize: 16,
          textAlign: 'left',
          lineHeight: 1.5
        }
      }
    };
    super({
      ...options,
      defaultOptions: {
        nodeMinNumber: 2,
        nodeMaxNumber: 2,
        // Strictly 2 nodes
        disableDeleteNode: true,
        disableAddNode: true
      },
      defaultData
    });
  }
  render() {
    super.render();
    const data = this.data;
    const wrapGroup = new draw_esm_min_ge();
    const {
      vsRadius
    } = this;

    // 1. Render Title
    let graphicsTitle;
    if (data.title?.show) {
      graphicsTitle = new RichText({
        ...data.title,
        onChange: text => {
          this.updateTitle(text);
        },
        onStyleChange: modifyStyle => {
          this.updateTitle(undefined, modifyStyle);
        },
        id: `graph-title`,
        editable: true,
        customData: {
          entityType: ENTITY_TYPE.RICH_TEXT
        }
      });
    }
    const nodeList = this.getNodeList();
    if (nodeList.length < 2) {
      return;
    }
    const node1 = nodeList[0];
    const node2 = nodeList[1];
    const nodeArr = [node1, node2];
    nodeArr.forEach(node => {
      node.onScaleEnd = () => {
        const {
          width
        } = node.group;
        const newData = nodeArr.map(item => ({
          id: item.id,
          data: {
            override: {
              size: {
                width
              }
            }
          }
        }));
        this.updateNodesData(newData);
      };
    });
    const node1Style = node1.style.getStyle();
    node1.render();
    wrapGroup.add(node1.group);
    node1.group.x = 0;
    node1.group.y = 0;
    node2.render();
    wrapGroup.add(node2.group);
    const fitWidth = Math.max(node1.getBounds().width, node2.getBounds().width);
    if (node1.getBounds().width !== fitWidth) {
      node1.render({
        width: fitWidth
      });
    }
    if (node2.getBounds().width !== fitWidth) {
      node2.render({
        width: fitWidth
      });
    }
    const fitHeight = Math.max(node1.getBounds().height, node2.getBounds().height);
    if (fitHeight !== node1.getBounds().height) {
      node1.render({
        width: fitWidth,
        height: fitHeight
      });
    }
    if (fitHeight !== node2.getBounds().height) {
      node2.render({
        width: fitWidth,
        height: fitHeight
      });
    }
    const totalWidth = node1.getBounds().width * 2 - node1.slant / 2;
    const totalHeight = node1.getBounds().height;
    node2.group.x = fitWidth - node1.slant / 2;
    const vsX = totalWidth / 2; // Should be centered on the overlap
    const vsY = totalHeight / 2; // Centered vertically

    const vsGroup = new flow_esm_min_m({
      flow: 'y',
      x: vsX - vsRadius,
      y: vsY - vsRadius,
      flowAlign: 'center',
      width: vsRadius * 2,
      height: vsRadius * 2
    });
    // White Circle Background
    const circle = new draw_esm_min_Fe({
      width: vsRadius * 2,
      height: vsRadius * 2,
      fill: node1Style.graph?.color[0]?.fill[0] || '#FFFFFF',
      stroke: node1Style.graph?.color[0]?.stroke[0] || '#1673FF',
      inFlow: false
    });
    vsGroup.add(circle);

    // VS Text
    const vsText = new draw_esm_min_i({
      // Text alignment might need adjustment
      text: 'VS',
      fontSize: 40,
      fontWeight: 'bold',
      fill: node1Style.graph?.color[0]?.stroke[0] || '#1673FF',
      // Blue text
      textAlign: 'center',
      verticalAlign: 'middle',
      fontFamily: 'Arial' // Or PingFang SC
    });
    vsGroup.add(vsText);
    wrapGroup.add(vsGroup);

    // 4. Assemble Layout
    if (graphicsTitle) {
      const flow = new flow_esm_min_m({
        flow: 'y',
        flowAlign: 'center',
        gap: 50,
        children: [graphicsTitle.getElement(), wrapGroup]
      });
      this.renderContainer.add(flow);
    } else {
      this.renderContainer.add(wrapGroup);
    }
  }
}
