class VerticalDevelopmentRoadmap extends SmartGraphics {
  NodeMap = {
    TitleStrokeBgNode: TitleStrokeBgNode
  };
  useNodeType = 'TitleStrokeBgNode';
  constructor(options) {
    super({
      ...options,
      defaultOptions: {
        nodeMaxNumber: 8,
        nodeMinNumber: 2
      },
      defaultData: {
        nodeStyle: {
          size: {
            width: 300
          },
          title: {
            fontSize: 20,
            fontWeight: 600
          },
          description: {
            fontSize: 16
          }
        }
      }
    });
  }
  render() {
    super.render();
    this.group = new draw_esm_min_ge();
    const nodeList = this.getNodeList();
    const firstNodeStyle = nodeList[0].style.getStyle();
    const gap = 30;
    const centerIconSize = {
      width: 240,
      height: 241
    };

    // 1. Create Center Icon
    const iconColor = '#1673FF';
    const svgString = vertical_development_roadmap_centerIcon.replace(/var\(--ICON_CUS_COLOR0\)/g, firstNodeStyle?.graph?.color[0].stroke[0]);
    const icon = new draw_esm_min_ti({
      url: core_esm_min_m.toURL(svgString, 'svg'),
      width: centerIconSize.width,
      height: centerIconSize.height
    });

    // 2. Create Left and Right Flows
    const leftFlow = new flow_esm_min_m({
      flow: 'y',
      gap: gap,
      flowAlign: 'top-right'
    });
    const rightFlow = new flow_esm_min_m({
      flow: 'y',
      gap: gap,
      flowAlign: 'top-left'
    });

    // 3. Distribute Nodes
    nodeList.forEach((node, index) => {
      const isLeft = index % 2 === 0;
      node.render({
        textAlign: isLeft ? 'right' : 'left'
      });
      if (isLeft) {
        leftFlow.add(node.group);
      } else {
        rightFlow.add(node.group);
      }
    });

    // 4. Calculate Dimensions and Position
    const maxHeight = Math.max(leftFlow.height, rightFlow.height);
    leftFlow.height = maxHeight;
    rightFlow.height = maxHeight;
    const leftHeight = leftFlow.height;
    const rightHeight = rightFlow.height;
    const iconHeight = centerIconSize.height;
    const totalHeight = Math.max(leftHeight, rightHeight, iconHeight);

    // Center layout vertically relative to the total height
    // "flow最小高度为centerIcon的高度 不够了撑开"
    // Since we are building from scratch, we can just position elements.

    const iconY = (totalHeight - iconHeight) / 2;
    icon.y = iconY;

    // Position Flows
    // Left Flow
    const leftY = (totalHeight - leftHeight) / 2;
    leftFlow.y = leftY;
    leftFlow.x = 0;

    // Icon X
    icon.x = leftFlow.width + 20; // 20px margin from left flow

    // Right Flow
    const rightY = (totalHeight - rightHeight) / 2;
    rightFlow.y = rightY;
    rightFlow.x = icon.x + icon.width + 20; // 20px margin from icon

    // 5. Add to Group
    this.group.add(leftFlow);
    this.group.add(icon);
    this.group.add(rightFlow);
    this.renderContainer.add(this.group);
  }
}
