class TitleCenterPolygonMatrix extends SmartGraphics {
  static type = 'TitleCenterPolygonMatrix';

  // Define default configuration
  NodeMap = {
    IconTitleDesColNode: IconTitleDesColNode
  };
  LayoutMap = {
    GridLayout: GridLayout
  };

  // Default use IconTitleDesColNode
  useNodeType = 'IconTitleDesColNode';
  useLayoutType = 'GridLayout';

  // Layout configuration
  layout = {
    lineCount: 2,
    gap: 12,
    // From Figma layout_AW28KL gap: 12px
    direction: 'x'
  };
  constructor(options) {
    super({
      ...options,
      defaultOptions: {
        nodeMinNumber: 4,
        nodeMaxNumber: 4,
        disableAddNode: true,
        disableDeleteNode: true
      },
      defaultData: {
        title: {
          style: {
            fontSize: 24
          }
        },
        nodeStyle: {
          size: {
            width: 262
          },
          title: {
            fontSize: 20,
            fontWeight: 600
          },
          description: {
            fontSize: 16
          },
          icon: {
            iconSize: {
              width: 36,
              height: 36
            }
          }
        }
      }
    });
  }

  /**
   * Initialize or update the nodes list
   * Ensure we have exactly 4 nodes for this specific matrix
   */
  onAfterInitData() {
    // If fewer than 4 nodes, fill up to 4
    if (this._initData && this._initData.nodeList) {
      const currentLength = this._initData.nodeList.length;
      if (currentLength < 4) {
        for (let i = currentLength; i < 4; i++) {
          this._initData.nodeList.push({
            id: (0,id/* createId */.s)(),
            title: `Title ${i}`,
            description: `Description ${i}`
          });
        }
      }
    }
  }
  render() {
    super.render();

    // 1. Ensure node list is prepared
    // We filter to use only the first 4 nodes if there are more
    const allNodes = this.getNodeList();
    const visibleNodes = allNodes.slice(0, 4);

    // 2. Update styles for specific corners based on position
    // TL (0): 24 24 0 24
    // TR (1): 24 24 24 0
    // BL (2): 24 0 24 24
    // BR (3): 0 24 24 24
    const cornerRadii = [[24, 24, 0, 24], [24, 24, 24, 0], [24, 0, 24, 24], [0, 24, 24, 24]];
    const sideLength = 128;
    const diagonal = sideLength * Math.sqrt(2);
    // Overlap = (Diagonal / 2) - (Gap / 2)
    // Add margin (e.g. 10) to avoid text touching the border
    const extraPadding = diagonal / 2 - this.layout.gap / 2 - 12;
    visibleNodes.forEach((node, index) => {
      // Update the graph style to set cornerRadius
      if (!node._data.override) node._data.override = {};
      if (!node._data.override.graph) node._data.override.graph = {};
      node._data.override.graph.cornerRadius = cornerRadii[index];

      // Update padding and text alignment to avoid overlap with center polygon
      // Left nodes (0, 2): Align Right, extra Right Padding
      if (index === 0 || index === 2) {
        node.itemAlign = 'left';
        // [Top, Right, Bottom, Left]
        // Default: [20, 20, 20, 20]
        node.padding = [20, extraPadding, 20, 20];
      }
      // Right nodes (1, 3): Align Left, extra Left Padding
      else if (index === 1 || index === 3) {
        node.itemAlign = 'right';
        node.padding = [20, 20, 20, extraPadding];
      }
    });

    // 3. Layout the nodes
    // We manually call layout with our 4 nodes
    this.layoutInstance.layoutOptions = {
      ...this.layout
    };
    // We need to make sure layoutInstance uses our visibleNodes
    // GridLayout.getList() usually takes targetNodeList
    const gridGroup = this.layoutInstance.getList(visibleNodes);
    this.renderContainer.add(gridGroup);

    // 4. Render Central Polygon (Diamond)
    const nodeMaxHeight = this.updateSize();
    this.renderCenterShape(gridGroup, nodeMaxHeight);
  }
  updateSize() {
    const nodeList = this.getNodeList();
    let maxHeight = 0;
    let maxWidth = 0;
    nodeList.forEach(node => {
      maxHeight = Math.max(maxHeight, node.group.height);
      maxWidth = Math.max(maxWidth, node.group.width);
    });
    nodeList.forEach(node => {
      node.updateGeometry(maxWidth);
      node.updateFlowSize({
        height: maxHeight
      });
    });
    return maxHeight;
  }
  renderCenterShape(gridGroup, nodeMaxHeight) {
    // Calculate center position
    const width = gridGroup.width;
    const height = nodeMaxHeight * 2 + this.layout.gap;
    const centerX = width / 2;
    const centerY = height / 2;
    const nodeList = this.getNodeList();
    const firstNodeStyle = nodeList[0].style.getStyle();

    // Diamond size
    // Side length is 128
    const sideLength = 128;
    // Bounding box size (diagonal) = side * sqrt(2)
    const diamondSize = sideLength * Math.sqrt(2);
    const diamondWidth = diamondSize;
    const diamondHeight = diamondSize;
    const halfW = diamondWidth / 2;
    const halfH = diamondHeight / 2;

    // Points for Diamond
    // Top, Right, Bottom, Left
    const points = [halfW, 0, diamondWidth, halfH, halfW, diamondHeight, 0, halfH];

    // Style for the center shape
    // White fill, Blue stroke
    const centerStyle = {
      fill: firstNodeStyle?.graph?.color[0]?.fill[0] || '#FFFFFF',
      stroke: firstNodeStyle?.graph?.color[0]?.stroke[0] || '#1673FF',
      // From Figma stroke_BDJBI6
      strokeWidth: 2
    };
    const centerGroup = new draw_esm_min_ge({
      x: centerX - halfW,
      y: centerY - halfH,
      width: diamondWidth,
      height: diamondHeight
    });
    const diamondBg = new draw_esm_min_Me({
      points: points,
      ...centerStyle,
      cornerRadius: 24 // Slight roundness for the diamond tips
    });
    centerGroup.add(diamondBg);

    // Add Text
    const {
      data: {
        title: {
          id = 'graphic-title',
          text,
          style = {}
        } = {}
      } = {}
    } = this;
    const titleText = new RichText({
      text: text || '添加标题',
      style: {
        fontSize: 24,
        fontWeight: 600,
        color: '#212930',
        // fill_WDUBSX
        textAlign: 'center',
        ...style,
        width: 110,
        // Padding
        height: 66,
        verticalAlign: 'middle'
      },
      x: diamondWidth / 2 - 55,
      y: diamondHeight / 2 - 33,
      // Approx vertical center
      editable: true,
      id: id,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT
      },
      onChange: newText => {
        this.updateTitle(newText);
      },
      onStyleChange: modifyStyle => {
        this.updateTitleStyle(modifyStyle);
      }
    });
    centerGroup.add(titleText.getElement());
    this.renderContainer.add(centerGroup);
  }
}
