class SerialBgTopCardNode extends IconCardNode {
  defaultWidth = 240;
  minWidth = 240;
  maxWidth = 1000;
  cardStrokeWidth = 0;
  cardPadding = [20, 16, 16, 16];
  cardFlowConfig = {
    flow: 'y',
    flowAlign: 'top',
    gap: 16,
    cornerRadius: 10
  };
  symbolSize = {
    width: 48,
    height: 48
  };
  getHeadElement() {
    const {
      width,
      height
    } = this.symbolSize;
    const nodeStyle = this.style.getStyle();
    const graphStyle = nodeStyle.graph;
    const group = new draw_esm_min_ge();
    const headBg = new hand_drawn_shape({
      shapeClass: draw_esm_min_we,
      width,
      height,
      fill: graphStyle.color[0].stroke[0],
      strokeWidth: 0,
      cornerRadius: 8,
      handDrawn: graphStyle.handDrawn,
      handDrawnStyle: {
        ...graphStyle.handDrawnStyle,
        fillWeight: 2,
        hachureGap: 2
      }
    });
    group.add(headBg);
    const serial = new RichText({
      text: this.index + 1,
      editableText: false,
      style: {
        ...nodeStyle.serial,
        color: this.style.getSerialVisibleColor('#212930', 'graph.color[0].stroke[0]'),
        width: width,
        height: height,
        textAlign: 'center',
        verticalAlign: 'middle'
      }
    });
    group.add(serial.getElement());
    this._headElement = group;
    return {
      element: group,
      size: {
        width
      }
    };
  }
  updateFlowSize(size) {
    if (size.height > 0) {
      this._cardWrap.height = size.height;
      if (this._handDrawnBg) {
        this._handDrawnBg.height = size.height;
      }
    }
  }
}
