/**
 * 根据 BaseNode 和 defaultSize 生成独立子类
 * @param {Class} BaseNode - 原始 Node 类
 * @param {Object} defaultSize - 默认尺寸配置
 * @returns {Class} 新子类
 */
function createNodeClass(BaseNode, defaultSize) {
  if (!defaultSize) {
    return class extends BaseNode {};
  }
  const NewClass = class extends BaseNode {
    constructor(options = {}) {
      super({
        ...options,
        defaultSize
      });
    }
  };
  return NewClass;
}
function createPPTListGraphicsClasses(options) {
  const {
    ClassName = PPTListGraphicsBase,
    zhName,
    name,
    NodeMap,
    useNodeType,
    layoutList,
    overrideOptions
  } = options;
  const classMap = {};
  const classList = [];
  layoutList.forEach((layout, index) => {
    const {
      defaultSize,
      lineCount,
      category,
      categoryName,
      nodeDragSortType,
      stretchLastRow = false,
      stretchLastRowChange = false,
      ...restLayout
    } = layout;
    let graphicsName = `${name}-${lineCount}`;
    let stretchLastRowList = [stretchLastRow];
    if (stretchLastRowChange && lineCount > 1) {
      stretchLastRowList = [true, false];
    }
    const currentName = graphicsName;
    const stretchLastRowListCount = stretchLastRowList.length;
    for (let i = 0; i < stretchLastRowListCount; i++) {
      const useStretchLastRow = stretchLastRowList[i];
      graphicsName = `${currentName}-${useStretchLastRow ? 'stretch' : 'no-stretch'}`;
      const newName = `${zhName}${useStretchLastRow ? '拉伸' : '不拉伸'}${index + 1}`;
      const newNodeMaps = {};
      for (const key in NodeMap) {
        const BaseClass = NodeMap[key];
        newNodeMaps[key] = createNodeClass(BaseClass, defaultSize);
      }
      const GraphicsClass = class extends ClassName {
        static graphicsName = graphicsName;
        static meta = {
          baseName: name,
          lineCount
        };
        NodeMap = newNodeMaps;
        useNodeType = useNodeType;
        layout = {
          ...restLayout,
          lineCount,
          stretchLastRow: useStretchLastRow
        };
        constructor(options = {}) {
          super(options, {
            ...overrideOptions,
            ...(nodeDragSortType ? {
              nodeDragSortType
            } : {})
          });
        }
      };
      classMap[graphicsName] = GraphicsClass;
      classList.push({
        name: newName,
        type: graphicsName
      });
    }
  });
  return {
    classList,
    classMap
  };
}
function createPPTListGraphicsClassesFromList(optionsList = []) {
  const allClassMap = {};
  const allClassList = [];
  optionsList.forEach(options => {
    const {
      classList,
      classMap
    } = createPPTListGraphicsClasses(options);
    classList.forEach(Cls => {
      allClassList.push(Cls);
    });
    Object.assign(allClassMap, classMap);
  });
  return {
    classes: allClassList,
    map: allClassMap
  };
}
