class GradientDescentLayout extends BaseLayout {
  constructor(options = {}) {
    super(options);
  }
  render() {
    this.group = new draw_esm_min_ge();
    const nodeList = this._ctx.getNodeList();
    const {
      layoutOptions = {}
    } = this;
    const {
      gap = 20,
      // 垂直间距 (支持数字或对象 {y: 20})
      indent = 30,
      // 水平错位距离（梯度）
      isSameSize = true,
      // 是否等宽等高
      padding = 0
    } = layoutOptions;

    // 归一化 gapY
    const gapY = typeof gap === 'number' ? gap : gap.y || 0;

    // 1. 渲染所有节点以获取初始尺寸
    nodeList.forEach(node => {
      node.render();
      this.group.add(node.group);
    });

    // 2. 如果需要等宽等高，计算最大尺寸并应用
    if (isSameSize) {
      let maxWidth = 0;
      let maxHeight = 0;
      nodeList.forEach(node => {
        const bounds = node.getBounds ? node.getBounds() : {
          width: node.width || 0,
          height: node.height || 0
        };
        if (bounds.width > maxWidth) maxWidth = bounds.width;
        if (bounds.height > maxHeight) maxHeight = bounds.height;
      });
      nodeList.forEach(node => {
        const nodeBounds = node.getBounds();
        if (nodeBounds.width !== maxWidth || nodeBounds.height !== maxHeight) {
          node.updateSize?.({
            width: maxWidth,
            height: maxHeight
          });
        }
      });
    }

    // 3. 布局计算
    let currentY = padding;
    nodeList.forEach((node, index) => {
      const bounds = node.getBounds ? node.getBounds() : {
        width: node.width || 0,
        height: node.height || 0
      };

      // 设置位置
      // X 轴：根据索引进行缩进 (indent)
      // Y 轴：累加高度 + 间距

      // 错位梯度下降：
      // 第一个：(padding, padding)
      // 第二个：(padding + indent, prevY + prevH + gapY)
      // ...

      const x = padding + index * indent;
      const y = currentY;
      node.group.x = x;
      node.group.y = y;

      // 更新 Y 轴游标
      currentY += bounds.height + gapY;
    });
  }
  getNewNodeInitSize() {
    return {
      width: this._ctx.getNodeList()[0].getBounds().width
    };
  }
  getScaleEndItemSize(size = {}) {
    let endWidth = size.width;
    const updateMsg = [];
    const nodeList = this._ctx.getNodeList();
    nodeList.forEach(node => {
      updateMsg.push({
        id: node.id,
        size: {
          width: endWidth
        }
      });
    });
    return updateMsg;
  }
}
