class ItemGradientDescentGraphics extends SmartGraphics {
  static type = 'ItemGradientDescentGraphics';
  NodeMap = {
    IconCardNode: IconCardNode
  };
  LayoutMap = {
    GradientDescentLayout: GradientDescentLayout
  };
  useNodeType = 'IconCardNode';
  useLayoutType = 'GradientDescentLayout';

  // Config matching Figma
  layout = {
    indent: 80,
    gap: 30,
    // vertical gap
    padding: 0,
    isSameSize: true
  };
  constructor(options = {}) {
    super((0,tools/* deepAssign */.Eg)({}, options, {
      defaultOptions: {
        nodeMaxNumber: 6,
        nodeMinNumber: 2
      },
      defaultData: {
        title: {
          text: '产品研发全流程',
          style: item_gradient_descent_defaultStyle.title
        },
        nodeStyle: {
          // Default styles if needed
        }
      }
    }));
  }
  render() {
    super.render();
    // 1. Render Nodes (calculate sizes)
    const visibleNodes = this.getNodeList();

    // 2. Run Layout (sets x, y)
    this.layoutInstance.layoutOptions = {
      ...this.layout
    };
    this.layoutInstance.render();

    // Create main flow for Title + Content
    const flow = new flow_esm_min_m({
      flow: 'y',
      flowAlign: 'center',
      gap: {
        x: 0,
        y: 50
      }
    });

    // Title
    const {
      data: {
        title: {
          id = 'graphic-title',
          text,
          style = {}
        } = {}
      } = {}
    } = this;
    if (text) {
      const titleText = new RichText({
        text,
        style: {
          ...item_gradient_descent_defaultStyle.title,
          ...style
        },
        onChange: text => {
          this.updateTitle(text);
        },
        editable: true,
        id,
        customData: {
          entityType: ENTITY_TYPE.RICH_TEXT
        },
        onStyleChange: modifyStyle => {
          this.updateTitleStyle(modifyStyle);
        }
      });
      flow.add(titleText.getElement());
    }
    const contentGroup = new draw_esm_min_ge();
    contentGroup.add(this.layoutInstance.group);
    const linesGroup = this.drawConnections(visibleNodes);
    contentGroup.addAt(linesGroup, 0);
    flow.add(contentGroup);
    this.renderContainer.add(flow);
  }
  drawConnections(nodes) {
    const group = new draw_esm_min_ge();
    const {
      indent = 80
    } = this.layout;
    const cornerRadius = 10; // Slightly tighter radius looks better for 40px offset
    const color = '#6C7D8F'; // stroke_5PYL4T
    const strokeWidth = 2;
    for (let i = 0; i < nodes.length - 1; i++) {
      const currNode = nodes[i];
      const nextNode = nodes[i + 1];
      const currBounds = currNode.getBounds();
      const nextBounds = nextNode.getBounds();

      // Calculate world coordinates
      const startWorldX = currBounds.x + currBounds.width; // Move left slightly to overlap
      const startWorldY = currBounds.y + currBounds.height / 2; // Right Middle

      const endWorldX = startWorldX + indent / 2;
      const endWorldY = nextBounds.y; // Top Edge + overlap

      // Convert world coordinates to inner coordinates of the group
      // Since the group will be in the same container as the nodes, we use the node's parent for conversion
      const startPoint = group.getInnerPoint({
        x: startWorldX,
        y: startWorldY
      });
      const endPoint = group.getInnerPoint({
        x: endWorldX,
        y: endWorldY
      });
      const startX = startPoint.x;
      const startY = startPoint.y;
      const endX = endPoint.x;
      const endY = endPoint.y;

      // Path Logic
      // M startX startY
      // L endX - radius startY
      // Q endX startY endX startY + radius
      // L endX endY

      // Note: We need to ensure endY > startY + radius.
      // With gap=30 and vertical positions, it should be fine.

      const pathData = `M ${startX} ${startY} L ${endX - cornerRadius} ${startY} Q ${endX} ${startY} ${endX} ${startY + cornerRadius} L ${endX} ${endY}`;
      const line = new draw_esm_min_hi({
        path: pathData,
        stroke: color,
        strokeWidth: strokeWidth,
        strokeJoin: 'round',
        strokeCap: 'round'
      });
      group.add(line);
      const arrowSize = 8;
      const arrowPath = `M ${endX - arrowSize / 2} ${endY - arrowSize} L ${endX} ${endY} L ${endX + arrowSize / 2} ${endY - arrowSize} Z`;

      // If filling
      const arrow = new draw_esm_min_hi({
        path: arrowPath,
        fill: color,
        stroke: 'none'
      });
      // If stroking
      // const arrow = new Path({
      //   path: [`M ${endX - 4} ${endY - 6} L ${endX} ${endY} L ${endX + 4} ${endY - 6}`],
      //   stroke: color,
      //   strokeWidth: strokeWidth,
      //   strokeCap: 'round',
      //   strokeJoin: 'round'
      // });

      group.add(arrow);
    }
    return group;
  }
}
