class CenterArrowMatrix extends SmartGraphics {
  static type = 'CenterArrowMatrix';
  NodeMap = {
    CenterArrowMatrixNode: CenterArrowMatrixNode
  };
  LayoutMap = {
    GridLayout: GridLayout
  };
  useNodeType = 'CenterArrowMatrixNode';
  useLayoutType = 'GridLayout';

  // Layout configuration
  layout = {
    lineCount: 2,
    gap: 12,
    // From Figma layout_AW28KL gap: 12px
    direction: 'x'
  };
  constructor(options) {
    super({
      ...options,
      defaultOptions: {
        nodeMinNumber: 4,
        nodeMaxNumber: 4,
        disableAddNode: true,
        disableDeleteNode: true
      },
      defaultData: {
        nodeStyle: {
          size: {
            width: 318
          },
          title: {
            fontSize: 20,
            fontWeight: 600
          },
          description: {
            fontSize: 16
          },
          icon: {
            iconSize: {
              width: 28,
              height: 28
            }
          }
        }
      }
    });
  }

  /**
   * Initialize or update the nodes list
   * Ensure we have exactly 4 nodes for this specific matrix
   */
  onAfterInitData() {
    // If fewer than 4 nodes, fill up to 4
    if (this._initData && this._initData.nodeList) {
      const currentLength = this._initData.nodeList.length;
      if (currentLength < 4) {
        for (let i = currentLength; i < 4; i++) {
          this._initData.nodeList.push({
            id: (0,id/* createId */.s)(),
            title: `Title ${i}`,
            description: `Description ${i}`
          });
        }
      }
    }
  }
  render() {
    super.render();

    // 1. Ensure node list is prepared
    // We filter to use only the first 4 nodes if there are more
    const allNodes = this.getNodeList();
    const visibleNodes = allNodes.slice(0, 4);
    const extraPadding = 72;
    visibleNodes.forEach((node, index) => {
      // Update the graph style to set cornerRadius
      if (!node._data.override) node._data.override = {};
      if (!node._data.override.graph) node._data.override.graph = {};

      // Update padding and text alignment to avoid overlap with center polygon
      // Left nodes (0, 2): Align Right, extra Right Padding
      // [Top, Right, Bottom, Left]
      if (index === 0) {
        node.itemAlign = 'top-left';
        node.padding = [16, extraPadding, 16, 16];
        node.textAlign = 'left';
      } else if (index === 1) {
        node.itemAlign = 'top-right';
        node.textAlign = 'right';
        node.padding = [16, 16, 16, extraPadding];
      } else if (index === 2) {
        node.textAlign = 'left';
        node.itemAlign = 'top-left';
        node.padding = [16, extraPadding, 16, 16];
      } else if (index === 3) {
        node.textAlign = 'right';
        node.itemAlign = 'top-right';
        node.padding = [16, 16, 16, extraPadding];
      }
    });

    // 3. Layout the nodes
    // We manually call layout with our 4 nodes
    this.layoutInstance.layoutOptions = {
      ...this.layout
    };
    // We need to make sure layoutInstance uses our visibleNodes
    // GridLayout.getList() usually takes targetNodeList
    const gridGroup = this.layoutInstance.getList(visibleNodes);
    const layoutWidth = this.layoutInstance.group.width;
    const flow = new flow_esm_min_m({
      width: layoutWidth,
      flow: 'y',
      gap: {
        x: 0,
        y: 24
      }
    });
    const titleFlow = new flow_esm_min_m({
      autoWidth: 1,
      flow: 'x',
      flowAlign: 'center'
    });
    const {
      data: {
        title: {
          id = 'graphic-title',
          text,
          style = {}
        } = {}
      } = {}
    } = this;
    const defaultTitleColor = this.getDefaultData().title?.style?.color;
    let titleColor = this.data.title.style.color;
    if (defaultTitleColor && titleColor === defaultTitleColor && visibleNodes[0]) {
      titleColor = visibleNodes[0].style.getVisibleColor(visibleNodes[0].style.getBgColorPathString(), '#212930');
    }
    const titleText = new RichText({
      text,
      style: {
        textAlign: 'center',
        ...style,
        color: titleColor,
        maxWidth: 752,
        lineClamp: Number.MAX_SAFE_INTEGER
      },
      onChange: text => {
        this.updateTitle(text);
      },
      editable: true,
      id,
      customData: {
        entityType: ENTITY_TYPE.RICH_TEXT
      },
      onStyleChange: modifyStyle => {
        this.updateTitleStyle(modifyStyle);
      }
    });
    const titleGroup = new draw_esm_min_ge({
      visible: true,
      locked: false,
      draggable: true
    });
    titleGroup.add(titleText.getElement());
    titleFlow.add(titleGroup);
    flow.add(titleFlow);
    flow.add(gridGroup);
    this.updateSize();
    this.renderContainer.add(flow);
  }
  updateSize() {
    const nodeList = this.getNodeList();
    let maxHeight = 0;
    nodeList.forEach(node => {
      maxHeight = Math.max(maxHeight, node.group.height);
    });
    nodeList.forEach(node => {
      node.updateFlowSize({
        height: maxHeight
      });
    });
  }
}
