function correctSmartGraphicType(type) {
  const shapeClassTags = tagMaps.filter(item => item.className.toLocaleLowerCase() === type?.toLocaleLowerCase())[0];
  return shapeClassTags?.className || type;
}
function getSmartGraphicClassByType(type) {
  const correctedType = correctSmartGraphicType(type);
  return graphicClass[correctedType];
}
/**
 *
 * @param {*} type
 * @returns
 */
function getSmartGraphicDefaultDataByType() {
  return {
    title: defaultTitle,
    colorCard: defaultColorCard,
    nodeStyle: defaultNodeStyle,
    nodeList: defaultNodeList
  };
}
function getSmartGraphicClassByTags(tags = []) {
  const result = tagMaps.filter(item => tags.some(t => item.tag.includes(t)));
  return result;
}
function getSmartGraphicTheme(themes, shapeClassname) {
  const shapeClassTags = tagMaps.filter(item => item.className.toLocaleLowerCase() === shapeClassname?.toLocaleLowerCase())[0];
  const {
    themeTag = []
  } = shapeClassTags;
  const useThemeTags = [];
  if (themeTag.length) {
    useThemeTags.push(...themeTag);
  } else {
    const themeList = themeManager.getThemeList();
    themeList.forEach(item => useThemeTags.push(item.name));
  }
  const result = [];
  useThemeTags.forEach(name => {
    const theme = themeManager.getTheme(name);
    result.push({
      name: name,
      data: theme.computed
    });
  });
  return result;
}
function getSmartGraphicSvgIcon(obj) {
  /**
   * 可扩展icon来源 iconPark或者其他库
   * iconPark的theme默认设置
   */
  const {
    name,
    theme = 'outline'
  } = obj;
  return getVarIconSvg(name, {
    theme
  });
}
function getSmartGraphicListData() {
  return SmartGraphicMenu;
}
